(window.NOVA_DATA = window.NOVA_DATA || {})["algebra"] = {"id": "algebra", "name": "Алгебра", "program": "Типовая учебная программа РК (обновлённое содержание образования). Темы сверять с действующим учебником.", "classes": {"7": {"sections": [{"title": "Степень и стандартный вид числа", "topics": [{"id": "a7-power", "title": "Степень с натуральным и целым показателем", "explain": "Степень aⁿ — произведение n одинаковых множителей a. a — основание, n — показатель. По определению a⁰ = 1 (a ≠ 0) и a⁻ⁿ = 1/aⁿ. Основные свойства: при умножении степеней с одинаковым основанием показатели складываются, при делении — вычитаются, при возведении степени в степень — перемножаются.", "formula": "aᵐ·aⁿ = aᵐ⁺ⁿ;  aᵐ : aⁿ = aᵐ⁻ⁿ;  (aᵐ)ⁿ = aᵐⁿ;  (ab)ⁿ = aⁿbⁿ;  a⁻ⁿ = 1/aⁿ", "levels": {"easy": [{"q": "Чему равно 3⁴?", "o": ["81", "12", "64", "27"], "a": 0, "e": "3·3·3·3 = 81."}, {"q": "Чему равно 7⁰?", "o": ["1", "0", "7", "не определено"], "a": 0, "e": "Любое ненулевое число в нулевой степени равно 1."}, {"q": "Упростите a³·a⁵.", "o": ["a⁸", "a¹⁵", "a²", "2a⁸"], "a": 0, "e": "Показатели складываются: 3 + 5."}, {"q": "Чему равно 2⁻³?", "o": ["1/8", "−8", "−6", "8"], "a": 0, "e": "2⁻³ = 1/2³ = 1/8."}], "medium": [{"q": "Упростите (x²)⁴ : x³.", "o": ["x⁵", "x³", "x⁹", "x⁶"], "a": 0, "e": "(x²)⁴ = x⁸; x⁸ : x³ = x⁵."}, {"q": "Вычислите (−2)⁵.", "o": ["−32", "32", "−10", "10"], "a": 0, "e": "Нечётная степень отрицательного числа отрицательна."}, {"q": "Вычислите 5⁷ : 5⁵.", "o": ["25", "5", "125", "10"], "a": 0, "e": "5⁷⁻⁵ = 5² = 25."}], "hard": [{"q": "Вычислите (2³·2⁻⁵)⁻¹.", "o": ["4", "1/4", "−4", "1/8"], "a": 0, "e": "2³·2⁻⁵ = 2⁻²; (2⁻²)⁻¹ = 2² = 4."}, {"q": "Вычислите 9⁵ : 27³.", "o": ["9", "3", "27", "1"], "a": 0, "e": "9⁵ = 3¹⁰, 27³ = 3⁹; 3¹⁰ : 3⁹ = 3."}, {"q": "Упростите (3a²b)³.", "o": ["27a⁶b³", "9a⁵b³", "27a⁵b", "3a⁶b³"], "a": 0, "e": "(ab)ⁿ = aⁿbⁿ: 3³·(a²)³·b³."}], "olympiad": [{"q": "Какая последняя цифра числа 2²⁰²⁵?", "o": ["2", "4", "8", "6"], "a": 0, "e": "Последние цифры степеней 2 повторяются: 2, 4, 8, 6. 2025 = 4·506 + 1 → как у 2¹."}, {"q": "Что больше: 2³⁰⁰ или 3²⁰⁰?", "o": ["3²⁰⁰", "2³⁰⁰", "они равны", "нельзя сравнить"], "a": 0, "e": "2³⁰⁰ = 8¹⁰⁰, 3²⁰⁰ = 9¹⁰⁰."}, {"q": "Вычислите (4¹⁰ + 4¹⁰ + 4¹⁰ + 4¹⁰) : 2²⁰.", "o": ["4", "1", "16", "2"], "a": 0, "e": "4·4¹⁰ = 4¹¹ = 2²²; 2²² : 2²⁰ = 4."}]}}, {"id": "a7-standard", "title": "Стандартный вид числа", "explain": "Стандартный вид числа — запись a·10ⁿ, где 1 ≤ a < 10, а n — целое число (порядок числа). Так удобно записывать очень большие и очень маленькие числа: расстояние до Солнца ≈ 1,5·10⁸ км, масса электрона ≈ 9,1·10⁻³¹ кг.", "formula": "a·10ⁿ, 1 ≤ a < 10", "levels": {"easy": [{"q": "Запишите 3000 в стандартном виде.", "o": ["3·10³", "30·10²", "0,3·10⁴", "3·10⁴"], "a": 0, "e": "3000 = 3·1000."}, {"q": "Какое число записано в стандартном виде?", "o": ["4,5·10⁶", "45·10⁵", "0,45·10⁷", "450·10⁴"], "a": 0, "e": "Множитель должен быть от 1 до 10."}, {"q": "Чему равно 10⁻²?", "o": ["0,01", "0,1", "−100", "−20"], "a": 0, "e": "10⁻² = 1/100."}], "medium": [{"q": "Запишите 0,00072 в стандартном виде.", "o": ["7,2·10⁻⁴", "72·10⁻⁵", "7,2·10⁻³", "0,72·10⁻³"], "a": 0, "e": "Запятую сдвигаем на 4 знака вправо."}, {"q": "Порядок числа 5,1·10⁷ равен…", "o": ["7", "5,1", "8", "−7"], "a": 0, "e": "Порядок — показатель степени 10."}, {"q": "Вычислите (2·10³)·(4·10⁵).", "o": ["8·10⁸", "8·10¹⁵", "6·10⁸", "8·10⁷"], "a": 0, "e": "2·4 = 8, 10³·10⁵ = 10⁸."}], "hard": [{"q": "Вычислите (6·10⁻³) : (3·10⁴) в стандартном виде.", "o": ["2·10⁻⁷", "2·10⁻¹", "2·10⁷", "3·10⁻⁷"], "a": 0, "e": "6 : 3 = 2, 10⁻³ : 10⁴ = 10⁻⁷."}, {"q": "Вычислите (5·10⁴)·(4·10³) в стандартном виде.", "o": ["2·10⁸", "20·10⁷", "2·10⁷", "9·10⁷"], "a": 0, "e": "20·10⁷ = 2·10⁸."}, {"q": "Скорость света 3·10⁵ км/с. Сколько км свет проходит за минуту?", "o": ["1,8·10⁷ км", "1,8·10⁶ км", "3·10⁶ км", "1,8·10⁸ км"], "a": 0, "e": "3·10⁵ · 60 = 180·10⁵ = 1,8·10⁷."}], "olympiad": [{"q": "Сколько цифр в числе 2¹⁰·5¹²?", "o": ["12", "11", "22", "13"], "a": 0, "e": "2¹⁰·5¹⁰·5² = 25·10¹⁰ — это 25 и 10 нулей, 12 цифр."}, {"q": "Масса Земли ≈ 6·10²⁴ кг, Луны ≈ 7,4·10²² кг. Во сколько раз масса Земли больше (примерно)?", "o": ["≈ 81", "≈ 8", "≈ 810", "≈ 1,2"], "a": 0, "e": "6·10²⁴ / 7,4·10²² ≈ 0,81·10² ≈ 81."}, {"q": "Запишите в стандартном виде 0,5·10⁻³ · 4·10⁻²", "o": ["2·10⁻⁵", "2·10⁻⁶", "20·10⁻⁶", "2·10⁻⁴"], "a": 0, "e": "0,5·4 = 2; 10⁻³·10⁻² = 10⁻⁵."}]}}]}, {"title": "Одночлены и многочлены", "topics": [{"id": "a7-monomial", "title": "Одночлены", "explain": "Одночлен — произведение чисел, переменных и их степеней (например, −3a²b). Стандартный вид одночлена: числовой множитель (коэффициент) на первом месте, каждая переменная встречается один раз. Степень одночлена — сумма показателей всех переменных. Подобные одночлены отличаются только коэффициентами — их можно складывать.", "levels": {"easy": [{"q": "Коэффициент одночлена −5x²y?", "o": ["−5", "5", "2", "x²y"], "a": 0, "e": "Числовой множитель."}, {"q": "Степень одночлена 4a³b²?", "o": ["5", "3", "4", "6"], "a": 0, "e": "3 + 2 = 5."}, {"q": "Какие одночлены подобные?", "o": ["3xy² и −xy²", "3xy² и 3x²y", "2a и 2b", "x² и x³"], "a": 0, "e": "Одинаковая буквенная часть."}], "medium": [{"q": "Упростите 2a·3ab².", "o": ["6a²b²", "5a²b²", "6ab²", "6a²b"], "a": 0, "e": "2·3 = 6, a·a = a²."}, {"q": "Упростите 7x²y − 3x²y + x²y.", "o": ["5x²y", "4x²y", "11x²y", "5x⁶y³"], "a": 0, "e": "7 − 3 + 1 = 5."}, {"q": "Возведите в квадрат одночлен −3m²n.", "o": ["9m⁴n²", "−9m⁴n²", "6m⁴n²", "9m²n"], "a": 0, "e": "(−3)² = 9, (m²)² = m⁴."}], "hard": [{"q": "Упростите (−2x²y)³·(xy²)².", "o": ["−8x⁸y⁷", "8x⁸y⁷", "−6x⁸y⁷", "−8x⁷y⁷"], "a": 0, "e": "(−2)³x⁶y³ · x²y⁴ = −8x⁸y⁷."}, {"q": "Найдите значение 0,2a³b при a = −5, b = 2.", "o": ["−50", "50", "−10", "−100"], "a": 0, "e": "0,2·(−125)·2 = −50."}, {"q": "Каким одночленом заменить *, чтобы *·3a²b = 12a⁵b³?", "o": ["4a³b²", "4a³b³", "9a³b²", "4a²b²"], "a": 0, "e": "12 : 3 = 4, a⁵ : a² = a³, b³ : b = b²."}], "olympiad": [{"q": "Одночлен A имеет степень 4, одночлен B — степень 7. Какова степень A²·B?", "o": ["15", "11", "28", "18"], "a": 0, "e": "2·4 + 7 = 15."}, {"q": "Найдите одночлен, квадрат которого равен 49a⁶b¹⁰ и коэффициент отрицательный.", "o": ["−7a³b⁵", "−7a⁴b⁸", "7a³b⁵", "−49a³b⁵"], "a": 0, "e": "(−7a³b⁵)² = 49a⁶b¹⁰."}, {"q": "При каком n одночлены 5xⁿy³ и −2x⁴yⁿ⁻¹ подобны?", "o": ["n = 4", "n = 3", "n = 2", "ни при каком"], "a": 0, "e": "Нужно n = 4 и n − 1 = 3 одновременно — n = 4."}]}}, {"id": "a7-polynomial", "title": "Многочлены. Действия с многочленами", "explain": "Многочлен — сумма одночленов. Чтобы привести его к стандартному виду, приводят подобные слагаемые. Многочлены складывают и вычитают, раскрывая скобки (если перед скобкой минус — знаки внутри меняются). Чтобы умножить многочлен на многочлен, каждый член первого умножают на каждый член второго.", "formula": "(a + b)(c + d) = ac + ad + bc + bd", "levels": {"easy": [{"q": "Раскройте скобки: −(2x − 5).", "o": ["−2x + 5", "−2x − 5", "2x − 5", "2x + 5"], "a": 0, "e": "Минус перед скобкой меняет знаки."}, {"q": "Приведите подобные: 3x + 2y − x + 4y.", "o": ["2x + 6y", "4x + 6y", "2x + 2y", "8xy"], "a": 0, "e": "3x − x = 2x, 2y + 4y = 6y."}, {"q": "Умножьте: 3(a + 2).", "o": ["3a + 6", "3a + 2", "a + 6", "3a + 5"], "a": 0, "e": "Каждое слагаемое умножаем на 3."}], "medium": [{"q": "Умножьте: 2x(x² − 3x + 1).", "o": ["2x³ − 6x² + 2x", "2x³ − 3x + 1", "2x² − 6x + 2", "2x³ − 6x + 2x"], "a": 0, "e": "Умножаем каждый член на 2x."}, {"q": "Упростите (3a² − 2a) − (a² − 5a).", "o": ["2a² + 3a", "2a² − 7a", "4a² − 7a", "2a² + 7a"], "a": 0, "e": "3a² − a² = 2a², −2a + 5a = 3a."}, {"q": "Умножьте (x + 3)(x − 2).", "o": ["x² + x − 6", "x² − x − 6", "x² + 5x − 6", "x² − 6"], "a": 0, "e": "x² − 2x + 3x − 6."}], "hard": [{"q": "Умножьте (2a − b)(3a + 2b).", "o": ["6a² + ab − 2b²", "6a² − ab − 2b²", "6a² + 7ab − 2b²", "5a² + ab − 2b²"], "a": 0, "e": "6a² + 4ab − 3ab − 2b²."}, {"q": "Решите уравнение (x + 2)(x − 3) − x(x − 4) = 9.", "o": ["x = 5", "x = 3", "x = −5", "x = 1"], "a": 0, "e": "x² − x − 6 − x² + 4x = 9 → 3x = 15."}, {"q": "Степень многочлена 3x⁴y − 2x²y³ + 7?", "o": ["5", "4", "3", "7"], "a": 0, "e": "Наибольшая степень одночленов: 4 + 1 = 5 и 2 + 3 = 5."}], "olympiad": [{"q": "На какое число при любом целом n делится (n + 5)(n + 6) − (n + 1)(n + 2)?", "o": ["на 4", "на 8", "на 5", "на 3"], "a": 0, "e": "Раскроем: n² + 11n + 30 − n² − 3n − 2 = 8n + 28 = 4(2n + 7) — всегда делится на 4."}, {"q": "При каком a многочлен (x + a)(x − 3) не содержит x в первой степени?", "o": ["a = 3", "a = −3", "a = 0", "a = 1"], "a": 0, "e": "Коэффициент при x: a − 3 = 0."}, {"q": "Найдите сумму коэффициентов многочлена (2x − 1)⁵ после раскрытия скобок.", "o": ["1", "0", "32", "−1"], "a": 0, "e": "Сумма коэффициентов = значение при x = 1: (2 − 1)⁵ = 1."}]}}, {"id": "a7-fsu", "title": "Формулы сокращённого умножения", "explain": "Формулы сокращённого умножения помогают быстро возводить в квадрат и куб и раскладывать выражения на множители. Квадрат суммы и разности, разность квадратов, куб суммы и разности, сумма и разность кубов.", "formula": "(a ± b)² = a² ± 2ab + b²;  a² − b² = (a − b)(a + b);  (a ± b)³ = a³ ± 3a²b + 3ab² ± b³;  a³ ± b³ = (a ± b)(a² ∓ ab + b²)", "levels": {"easy": [{"q": "Раскройте (x + 3)².", "o": ["x² + 6x + 9", "x² + 9", "x² + 3x + 9", "x² + 6x + 6"], "a": 0, "e": "Квадрат суммы."}, {"q": "Разложите x² − 25.", "o": ["(x − 5)(x + 5)", "(x − 5)²", "(x − 25)(x + 1)", "(x + 5)²"], "a": 0, "e": "Разность квадратов."}, {"q": "Раскройте (a − 4)².", "o": ["a² − 8a + 16", "a² − 16", "a² + 8a + 16", "a² − 4a + 16"], "a": 0, "e": "Квадрат разности."}], "medium": [{"q": "Вычислите 51² с помощью формулы.", "o": ["2601", "2501", "2551", "2611"], "a": 0, "e": "(50 + 1)² = 2500 + 100 + 1."}, {"q": "Вычислите 47·53.", "o": ["2491", "2500", "2509", "2481"], "a": 0, "e": "(50 − 3)(50 + 3) = 2500 − 9."}, {"q": "Раскройте (2a − 3b)².", "o": ["4a² − 12ab + 9b²", "4a² − 9b²", "4a² − 6ab + 9b²", "2a² − 12ab + 3b²"], "a": 0, "e": "(2a)² − 2·2a·3b + (3b)²."}], "hard": [{"q": "Раскройте (x + 2)³.", "o": ["x³ + 6x² + 12x + 8", "x³ + 8", "x³ + 3x² + 3x + 8", "x³ + 6x² + 6x + 8"], "a": 0, "e": "Куб суммы: x³ + 3·x²·2 + 3·x·4 + 8."}, {"q": "Разложите 8a³ − 27.", "o": ["(2a − 3)(4a² + 6a + 9)", "(2a − 3)³", "(2a − 3)(4a² − 6a + 9)", "(8a − 27)(a² + 1)"], "a": 0, "e": "Разность кубов: (2a)³ − 3³."}, {"q": "Упростите (x − 1)(x + 1)(x² + 1).", "o": ["x⁴ − 1", "x⁴ + 1", "x⁴ − 2x² + 1", "x³ − 1"], "a": 0, "e": "(x² − 1)(x² + 1) = x⁴ − 1."}], "olympiad": [{"q": "Вычислите 1001² − 999².", "o": ["4000", "2000", "2", "4"], "a": 0, "e": "(1001 − 999)(1001 + 999) = 2·2000."}, {"q": "Известно, что a + b = 7, ab = 10. Найдите a² + b².", "o": ["29", "49", "39", "69"], "a": 0, "e": "a² + b² = (a + b)² − 2ab = 49 − 20."}, {"q": "Найдите наименьшее значение выражения x² − 6x + 14.", "o": ["5", "14", "0", "−9"], "a": 0, "e": "x² − 6x + 14 = (x − 3)² + 5 ≥ 5."}]}}, {"id": "a7-factor", "title": "Разложение многочленов на множители", "explain": "Разложить многочлен на множители — записать его как произведение. Способы: вынесение общего множителя за скобки, группировка, применение формул сокращённого умножения. Разложение помогает сокращать дроби и решать уравнения вида «произведение равно нулю».", "formula": "ab + ac = a(b + c);  ab = 0 ⇔ a = 0 или b = 0", "levels": {"easy": [{"q": "Вынесите общий множитель: 6x + 9.", "o": ["3(2x + 3)", "6(x + 9)", "3(2x + 9)", "9(x + 1)"], "a": 0, "e": "НОД(6, 9) = 3."}, {"q": "Вынесите общий множитель: a² + 5a.", "o": ["a(a + 5)", "a²(1 + 5)", "5a(a + 1)", "a(a + 5a)"], "a": 0, "e": "Общий множитель — a."}, {"q": "Решите уравнение x(x − 4) = 0.", "o": ["0 и 4", "только 4", "только 0", "−4 и 0"], "a": 0, "e": "Произведение равно нулю, если один из множителей равен нулю."}], "medium": [{"q": "Разложите методом группировки: ab + 3a + 2b + 6.", "o": ["(a + 2)(b + 3)", "(a + 3)(b + 2)", "(a + 6)(b + 1)", "(ab + 6)(1 + 5)"], "a": 0, "e": "a(b + 3) + 2(b + 3)."}, {"q": "Разложите x² − 10x + 25.", "o": ["(x − 5)²", "(x + 5)²", "(x − 5)(x + 5)", "(x − 25)(x − 1)"], "a": 0, "e": "Квадрат разности."}, {"q": "Решите уравнение x² − 9x = 0.", "o": ["0 и 9", "3 и −3", "9", "0 и −9"], "a": 0, "e": "x(x − 9) = 0."}], "hard": [{"q": "Разложите 3x³ − 12x.", "o": ["3x(x − 2)(x + 2)", "3x(x² − 4x)", "3(x³ − 4x)", "3x(x − 2)²"], "a": 0, "e": "3x(x² − 4) = 3x(x − 2)(x + 2)."}, {"q": "Решите уравнение x³ = 16x.", "o": ["−4, 0, 4", "4", "0 и 4", "−4 и 4"], "a": 0, "e": "x(x² − 16) = 0."}, {"q": "Разложите a³ − a²b − ab² + b³.", "o": ["(a − b)²(a + b)", "(a + b)²(a − b)", "(a − b)³", "(a + b)³"], "a": 0, "e": "a²(a − b) − b²(a − b) = (a − b)(a² − b²)."}], "olympiad": [{"q": "Разложите x⁴ + 4 на множители.", "o": ["(x² − 2x + 2)(x² + 2x + 2)", "(x² + 2)²", "не раскладывается", "(x² − 2)(x² + 2)"], "a": 0, "e": "x⁴ + 4x² + 4 − 4x² = (x² + 2)² − (2x)² — приём Софи Жермен."}, {"q": "Докажите, что n³ − n делится на 6 при любом целом n. Почему?", "o": ["n³ − n = (n − 1)n(n + 1) — произведение трёх последовательных чисел", "n³ всегда чётно", "n³ − n = 6n", "это неверно"], "a": 0, "e": "Среди трёх подряд идущих чисел есть чётное и кратное трём."}, {"q": "Найдите все целые решения xy + x + y = 5.", "o": ["(0;5), (5;0), (1;2), (2;1), (−2;−7), (−7;−2), (−3;−4), (−4;−3)", "(1;2) и (2;1)", "(0;5) и (5;0)", "решений нет"], "a": 0, "e": "Прибавим 1: (x + 1)(y + 1) = 6; переберём делители ±1, ±2, ±3, ±6."}]}}, {"id": "a7-fractions", "title": "Алгебраические дроби", "explain": "Алгебраическая дробь — дробь, числитель и знаменатель которой многочлены. Знаменатель не может равняться нулю — отсюда область допустимых значений. Дробь сокращают, разложив числитель и знаменатель на множители. Складывают и вычитают дроби, приводя к общему знаменателю, умножают и делят — как обыкновенные дроби.", "formula": "a/b · c/d = ac/bd;  a/b : c/d = ad/bc;  a/c + b/c = (a + b)/c", "levels": {"easy": [{"q": "При каком x дробь 5/(x − 3) не имеет смысла?", "o": ["x = 3", "x = 0", "x = 5", "x = −3"], "a": 0, "e": "Знаменатель не может быть нулём."}, {"q": "Сократите дробь 6x²/(9x).", "o": ["2x/3", "6x/9", "2/3", "3x/2"], "a": 0, "e": "Делим на 3x."}, {"q": "Сложите: a/5 + 2a/5.", "o": ["3a/5", "3a/10", "2a²/5", "a/5"], "a": 0, "e": "Одинаковый знаменатель — складываем числители."}], "medium": [{"q": "Сократите (x² − 4)/(x + 2).", "o": ["x − 2", "x + 2", "x² − 2", "1/(x − 2)"], "a": 0, "e": "(x − 2)(x + 2)/(x + 2)."}, {"q": "Выполните: 1/x + 1/y.", "o": ["(x + y)/xy", "2/(x + y)", "1/(x + y)", "2/xy"], "a": 0, "e": "Общий знаменатель xy."}, {"q": "Умножьте: (2a/b)·(b²/4a²).", "o": ["b/(2a)", "2b/a", "b²/(2a)", "1/2"], "a": 0, "e": "2ab²/(4a²b) = b/(2a)."}], "hard": [{"q": "Упростите (a² − 9)/(a² + 6a + 9).", "o": ["(a − 3)/(a + 3)", "(a + 3)/(a − 3)", "1", "(a − 3)/a"], "a": 0, "e": "(a − 3)(a + 3)/(a + 3)²."}, {"q": "Вычислите 1/(x − 1) − 1/(x + 1).", "o": ["2/(x² − 1)", "−2/(x² − 1)", "0", "2x/(x² − 1)"], "a": 0, "e": "(x + 1 − x + 1)/(x² − 1)."}, {"q": "Разделите (x² − 1)/x на (x + 1)/x².", "o": ["x(x − 1)", "(x − 1)/x", "x − 1", "x²(x − 1)"], "a": 0, "e": "(x − 1)(x + 1)/x · x²/(x + 1) = x(x − 1)."}], "olympiad": [{"q": "Вычислите 1/(1·2) + 1/(2·3) + … + 1/(9·10).", "o": ["9/10", "1", "1/10", "10/9"], "a": 0, "e": "1/(n(n+1)) = 1/n − 1/(n+1), сумма «телескопически» сокращается: 1 − 1/10."}, {"q": "Известно, что x + 1/x = 3. Найдите x² + 1/x².", "o": ["7", "9", "11", "5"], "a": 0, "e": "(x + 1/x)² = x² + 2 + 1/x² = 9."}, {"q": "При каких целых n дробь (n + 5)/(n + 1) — целое число?", "o": ["n ∈ {−5, −3, −2, 0, 1, 3}", "n = 0", "n = 1 и n = 3", "при всех"], "a": 0, "e": "(n + 5)/(n + 1) = 1 + 4/(n + 1); n + 1 — делитель 4: ±1, ±2, ±4."}]}}]}, {"title": "Функции и уравнения", "topics": [{"id": "a7-function", "title": "Функция. Линейная функция и её график", "explain": "Функция — правило, по которому каждому значению x соответствует ровно одно значение y. Линейная функция задаётся формулой y = kx + b, её график — прямая. Коэффициент k (угловой коэффициент) показывает наклон: при k > 0 функция возрастает, при k < 0 — убывает. Число b — ордината точки пересечения с осью Oy. Если k одинаковые, прямые параллельны. Прямая пропорциональность — частный случай: y = kx.", "formula": "y = kx + b", "levels": {"easy": [{"q": "Какой график у функции y = 2x + 1?", "o": ["прямая", "парабола", "гипербола", "окружность"], "a": 0, "e": "Линейная функция — прямая."}, {"q": "Где график y = 3x − 4 пересекает ось Oy?", "o": ["в точке (0; −4)", "в точке (−4; 0)", "в точке (0; 3)", "в точке (4; 0)"], "a": 0, "e": "При x = 0 y = b."}, {"q": "Возрастает или убывает функция y = −2x + 5?", "o": ["убывает", "возрастает", "постоянна", "сначала растёт, потом убывает"], "a": 0, "e": "k < 0."}], "medium": [{"q": "Найдите значение y = 4x − 7 при x = 3.", "o": ["5", "19", "−5", "12"], "a": 0, "e": "4·3 − 7 = 5."}, {"q": "При каком x функция y = 2x − 6 равна нулю?", "o": ["x = 3", "x = −3", "x = 6", "x = 0"], "a": 0, "e": "2x − 6 = 0."}, {"q": "Какая прямая параллельна y = 3x + 1?", "o": ["y = 3x − 5", "y = −3x + 1", "y = x + 3", "y = (1/3)x"], "a": 0, "e": "Одинаковый угловой коэффициент."}], "hard": [{"q": "Прямая проходит через (0; 2) и (3; 8). Её уравнение?", "o": ["y = 2x + 2", "y = 3x + 2", "y = 2x + 8", "y = 6x + 2"], "a": 0, "e": "b = 2, k = (8 − 2)/3 = 2."}, {"q": "Найдите точку пересечения прямых y = 2x + 1 и y = −x + 7.", "o": ["(2; 5)", "(3; 7)", "(1; 3)", "(−2; −3)"], "a": 0, "e": "2x + 1 = −x + 7 → x = 2."}, {"q": "Проходит ли график y = −3x + 4 через точку (2; −2)?", "o": ["да", "нет", "только при x = 0", "нельзя определить"], "a": 0, "e": "−3·2 + 4 = −2."}], "olympiad": [{"q": "При каком k прямые y = kx + 3 и y = (2k − 1)x − 4 параллельны?", "o": ["k = 1", "k = −1", "k = 0", "k = 3"], "a": 0, "e": "k = 2k − 1."}, {"q": "Найдите площадь треугольника, который прямая y = −2x + 6 отсекает от координатных углов.", "o": ["9", "18", "6", "12"], "a": 0, "e": "Пересечения (0; 6) и (3; 0); S = 6·3/2."}, {"q": "Функция f(x) = kx + b, f(1) = 5, f(3) = 11. Найдите f(10).", "o": ["32", "30", "35", "29"], "a": 0, "e": "k = 3, b = 2: f(10) = 32."}]}}, {"id": "a7-linear-eq", "title": "Линейные уравнения с одной переменной", "explain": "Линейное уравнение имеет вид ax = b. Если a ≠ 0, у него один корень x = b/a. Если a = 0 и b = 0 — корней бесконечно много, если a = 0, b ≠ 0 — корней нет. Решая уравнение, раскрывают скобки, переносят слагаемые с переменной в одну часть, числа — в другую (меняя знак), приводят подобные. С помощью уравнений решают текстовые задачи.", "formula": "ax = b → x = b/a (a ≠ 0)", "levels": {"easy": [{"q": "Решите: 3x = 12.", "o": ["4", "36", "9", "15"], "a": 0, "e": "x = 12 : 3."}, {"q": "Решите: x − 7 = 2.", "o": ["9", "−5", "5", "14"], "a": 0, "e": "x = 2 + 7."}, {"q": "Решите: 5x + 3 = 18.", "o": ["3", "4,2", "15", "21"], "a": 0, "e": "5x = 15."}], "medium": [{"q": "Решите: 2(x − 3) = x + 4.", "o": ["10", "7", "2", "−10"], "a": 0, "e": "2x − 6 = x + 4 → x = 10."}, {"q": "Решите: x/3 + x/6 = 5.", "o": ["10", "15", "30", "5"], "a": 0, "e": "Умножим на 6: 2x + x = 30."}, {"q": "Сколько корней у уравнения 2x + 5 = 2x + 7?", "o": ["ни одного", "один", "два", "бесконечно много"], "a": 0, "e": "Получаем 5 = 7 — неверно."}], "hard": [{"q": "Сумма трёх последовательных чисел 96. Наименьшее?", "o": ["31", "32", "30", "33"], "a": 0, "e": "x + x + 1 + x + 2 = 96 → x = 31."}, {"q": "Отец старше сына на 26 лет, через 4 года будет старше в 3 раза. Возраст сына?", "o": ["9", "13", "4", "10"], "a": 0, "e": "x + 30 = 3(x + 4) → x = 9."}, {"q": "Решите: (x + 1)/2 − (x − 2)/3 = 2.", "o": ["5", "4", "7", "1"], "a": 0, "e": "3(x + 1) − 2(x − 2) = 12 → x + 7 = 12."}], "olympiad": [{"q": "При каком a уравнение ax = a имеет бесконечно много корней?", "o": ["a = 0", "a = 1", "a = −1", "ни при каком"], "a": 0, "e": "0·x = 0 верно при любом x."}, {"q": "Бассейн заполняется первой трубой за 6 ч, второй — за 3 ч. За сколько заполнят обе вместе?", "o": ["2 ч", "4,5 ч", "9 ч", "1,5 ч"], "a": 0, "e": "1/6 + 1/3 = 1/2 бассейна в час."}, {"q": "Решите |x − 3| = 5.", "o": ["−2 и 8", "8", "−8 и 2", "2 и 8"], "a": 0, "e": "x − 3 = 5 или x − 3 = −5."}]}}, {"id": "a7-systems", "title": "Системы линейных уравнений с двумя переменными", "explain": "Решение системы — пара чисел (x; y), обращающая каждое уравнение в верное равенство. Способы решения: подстановка (выражаем одну переменную и подставляем во второе уравнение), сложение (складываем уравнения, чтобы одна переменная исчезла), графический (точка пересечения прямых). Система может иметь одно решение, не иметь решений (параллельные прямые) или иметь бесконечно много (совпадающие прямые).", "check": true, "levels": {"easy": [{"q": "Является ли (2; 1) решением системы x + y = 3, x − y = 1?", "o": ["да", "нет", "только первого уравнения", "только второго"], "a": 0, "e": "2 + 1 = 3, 2 − 1 = 1."}, {"q": "Решите: x + y = 10, x − y = 2.", "o": ["(6; 4)", "(4; 6)", "(5; 5)", "(8; 2)"], "a": 0, "e": "Сложим: 2x = 12."}, {"q": "Сколько решений, если прямые системы параллельны?", "o": ["ни одного", "одно", "два", "бесконечно много"], "a": 0, "e": "Параллельные прямые не пересекаются."}], "medium": [{"q": "Решите: y = 2x, x + y = 9.", "o": ["(3; 6)", "(6; 3)", "(2; 7)", "(4,5; 4,5)"], "a": 0, "e": "x + 2x = 9."}, {"q": "Решите: 2x + 3y = 13, x − y = −1.", "o": ["(2; 3)", "(3; 2)", "(1; 2)", "(−1; 5)"], "a": 0, "e": "x = y − 1: 2y − 2 + 3y = 13 → y = 3."}, {"q": "В классе 30 учеников, девочек на 4 больше, чем мальчиков. Сколько мальчиков?", "o": ["13", "17", "15", "14"], "a": 0, "e": "x + y = 30, y − x = 4."}], "hard": [{"q": "Решите: 3x − 2y = 4, 5x + 2y = 12.", "o": ["(2; 1)", "(1; 2)", "(2; −1)", "(4; 4)"], "a": 0, "e": "Сложим: 8x = 16."}, {"q": "При каком a система x + y = 2, 2x + 2y = a имеет бесконечно много решений?", "o": ["a = 4", "a = 2", "a = 0", "ни при каком"], "a": 0, "e": "Второе уравнение должно быть первым, умноженным на 2."}, {"q": "2 тетради и 3 ручки стоят 340 ₸, 3 тетради и 2 ручки — 360 ₸. Цена тетради?", "o": ["80 ₸", "60 ₸", "70 ₸", "100 ₸"], "a": 0, "e": "Сложив: 5(t + r) = 700 → t + r = 140; вычтя: t − r = 20."}], "olympiad": [{"q": "Решите систему x + y = 5, y + z = 7, z + x = 6.", "o": ["(2; 3; 4)", "(3; 2; 4)", "(1; 4; 3)", "(2; 4; 3)"], "a": 0, "e": "Сложим: 2(x + y + z) = 18, сумма 9; отсюда z = 4, x = 2, y = 3."}, {"q": "При каком k система y = kx + 1, y = 3x − 2 не имеет решений?", "o": ["k = 3", "k = −3", "k = 1", "при любом k"], "a": 0, "e": "Параллельные прямые: одинаковый k, разные b."}, {"q": "Лодка за 3 ч по течению и 2 ч против прошла 48 км, а за 2 ч по течению и 3 ч против — 42 км. Скорость течения?", "o": ["3 км/ч", "2 км/ч", "1 км/ч", "1,2 км/ч"], "a": 0, "e": "3(v+u) + 2(v−u) = 48 и 2(v+u) + 3(v−u) = 42 дают 5v + u = 48 и 5v − u = 42, откуда 2u = 6, u = 3 км/ч (v = 9 км/ч)."}]}}]}, {"title": "Элементы статистики", "topics": [{"id": "a7-stat", "title": "Элементы статистики: среднее, мода, медиана, размах", "explain": "Статистика изучает наборы данных. Среднее арифметическое — сумма чисел, делённая на их количество. Мода — значение, которое встречается чаще всего. Медиана — число в середине упорядоченного ряда (при чётном количестве — среднее двух средних чисел). Размах — разность наибольшего и наименьшего значений.", "check": true, "levels": {"easy": [{"q": "Среднее арифметическое чисел 2, 4, 6?", "o": ["4", "12", "6", "3"], "a": 0, "e": "(2 + 4 + 6) / 3."}, {"q": "Мода ряда 3, 5, 5, 7, 8?", "o": ["5", "7", "5,6", "3"], "a": 0, "e": "Чаще всего встречается 5."}, {"q": "Размах ряда 4, 9, 1, 7?", "o": ["8", "9", "5,25", "6"], "a": 0, "e": "9 − 1."}], "medium": [{"q": "Медиана ряда 7, 1, 5, 3, 9?", "o": ["5", "3", "7", "5,2"], "a": 0, "e": "Упорядочим: 1, 3, 5, 7, 9 — середина 5."}, {"q": "Медиана ряда 2, 4, 6, 10?", "o": ["5", "4", "6", "5,5"], "a": 0, "e": "(4 + 6) / 2."}, {"q": "Оценки: 5, 4, 4, 3, 5, 5. Среднее?", "o": ["≈ 4,33", "4", "4,5", "5"], "a": 0, "e": "26 / 6 ≈ 4,33."}], "hard": [{"q": "Среднее пяти чисел 8. Добавили число 14. Новое среднее?", "o": ["9", "11", "8", "10"], "a": 0, "e": "Сумма 40 + 14 = 54, 54 / 6 = 9."}, {"q": "Какую оценку нужно получить, чтобы среднее из 4, 3, 5 стало 4,25?", "o": ["5", "4", "3", "6"], "a": 0, "e": "Нужна сумма 17; 17 − 12 = 5."}, {"q": "Изменится ли медиана ряда 1, 2, 3, 4, 100, если 100 заменить на 1000?", "o": ["нет", "да, увеличится", "да, уменьшится", "станет 1000"], "a": 0, "e": "Медиана устойчива к выбросам."}], "olympiad": [{"q": "Среднее 10 чисел равно 7. Одно число убрали — среднее стало 6. Какое число убрали?", "o": ["16", "7", "1", "13"], "a": 0, "e": "70 − 54 = 16."}, {"q": "Ряд из 7 чисел: медиана 10, мода 12, среднее 9. Может ли наибольшее число быть 12?", "o": ["да", "нет", "только если все числа равны", "нельзя определить"], "a": 0, "e": "Да, например 4, 6, 7, 10, 12, 12, 12: медиана 10, мода 12, сумма 63, среднее 9."}, {"q": "Почему зарплату в стране часто описывают медианой, а не средним?", "o": ["несколько очень больших зарплат сильно завышают среднее", "медиану легче посчитать", "среднее нельзя посчитать", "так требует закон"], "a": 0, "e": "Медиана лучше показывает типичное значение."}]}}]}]}, "8": {"sections": [{"title": "Квадратные корни", "topics": [{"id": "a8-sqrt", "title": "Квадратный корень. Свойства арифметического корня", "explain": "Арифметический квадратный корень из неотрицательного числа a — неотрицательное число, квадрат которого равен a. Из отрицательных чисел квадратный корень (в действительных числах) не извлекается. Свойства: корень из произведения равен произведению корней, корень из дроби — дроби корней, √(a²) = |a|.", "formula": "√(ab) = √a·√b;  √(a/b) = √a/√b;  √(a²) = |a|;  (√a)² = a", "levels": {"easy": [{"q": "Чему равен √49?", "o": ["7", "−7", "±7", "24,5"], "a": 0, "e": "Арифметический корень неотрицателен."}, {"q": "Чему равен √0,25?", "o": ["0,5", "0,05", "0,125", "5"], "a": 0, "e": "0,5² = 0,25."}, {"q": "Имеет ли смысл выражение √(−16)?", "o": ["нет", "да, −4", "да, 4", "да, ±4"], "a": 0, "e": "Квадрат любого действительного числа неотрицателен."}], "medium": [{"q": "Вычислите √(16·81).", "o": ["36", "97", "1296", "13"], "a": 0, "e": "√16·√81 = 4·9."}, {"q": "Вычислите √(9/25).", "o": ["3/5", "9/5", "3/25", "0,36"], "a": 0, "e": "√9/√25."}, {"q": "Вычислите √(2)·√(18).", "o": ["6", "√20", "36", "9"], "a": 0, "e": "√36 = 6."}], "hard": [{"q": "Чему равно √((−5)²)?", "o": ["5", "−5", "±5", "25"], "a": 0, "e": "√(a²) = |a|."}, {"q": "Упростите √(a²) при a < 0.", "o": ["−a", "a", "a²", "|a|²"], "a": 0, "e": "|a| = −a при a < 0."}, {"q": "Вычислите √(1,21·0,0036).", "o": ["0,066", "0,66", "0,0066", "6,6"], "a": 0, "e": "1,1·0,06 = 0,066."}], "olympiad": [{"q": "Вычислите √(17² − 8²).", "o": ["15", "9", "25", "√9"], "a": 0, "e": "√(289 − 64) = √225."}, {"q": "Найдите значение √(3 + 2√2).", "o": ["1 + √2", "√5", "2 + √2", "√3 + √2"], "a": 0, "e": "(1 + √2)² = 1 + 2√2 + 2 = 3 + 2√2."}, {"q": "Сколько целых чисел между √10 и √99?", "o": ["6", "7", "89", "5"], "a": 0, "e": "√10 ≈ 3,16, √99 ≈ 9,95: целые 4, 5, 6, 7, 8, 9."}]}}, {"id": "a8-radicals", "title": "Действительные числа. Преобразование выражений с корнями", "explain": "Рациональные числа можно записать дробью m/n; иррациональные (√2, π) — бесконечные непериодические десятичные дроби. Вместе они образуют множество действительных чисел. Выражения с корнями упрощают: выносят множитель из-под корня (√50 = 5√2), вносят множитель под корень, приводят подобные корни, избавляются от иррациональности в знаменателе.", "formula": "√(a²b) = a√b (a ≥ 0);  1/√a = √a/a;  1/(√a − √b) = (√a + √b)/(a − b)", "levels": {"easy": [{"q": "Какое число иррациональное?", "o": ["√2", "√9", "0,25", "1/3"], "a": 0, "e": "√2 нельзя записать обыкновенной дробью."}, {"q": "Вынесите множитель из-под корня: √12.", "o": ["2√3", "3√2", "4√3", "6√2"], "a": 0, "e": "√(4·3) = 2√3."}, {"q": "Упростите 3√5 + 2√5.", "o": ["5√5", "5√10", "6√5", "√25"], "a": 0, "e": "Подобные корни складываются как подобные слагаемые."}], "medium": [{"q": "Упростите √50 − √18.", "o": ["2√2", "√32", "4√2", "8√2"], "a": 0, "e": "5√2 − 3√2."}, {"q": "Освободитесь от иррациональности: 6/√3.", "o": ["2√3", "√3", "6√3", "3√2"], "a": 0, "e": "6√3/3."}, {"q": "Сравните 3√2 и 2√3.", "o": ["3√2 > 2√3", "3√2 < 2√3", "равны", "нельзя сравнить"], "a": 0, "e": "√18 > √12."}], "hard": [{"q": "Упростите (√7 − √3)(√7 + √3).", "o": ["4", "10", "√4", "√21"], "a": 0, "e": "Разность квадратов: 7 − 3."}, {"q": "Освободитесь от иррациональности: 1/(√5 − 2).", "o": ["√5 + 2", "√5 − 2", "(√5 + 2)/9", "1/(5 − 4)"], "a": 0, "e": "(√5 + 2)/(5 − 4)."}, {"q": "Упростите (√3 + 1)².", "o": ["4 + 2√3", "4", "3 + 2√3", "4 + √3"], "a": 0, "e": "3 + 2√3 + 1."}], "olympiad": [{"q": "Вычислите 1/(1 + √2) + 1/(√2 + √3) + … + 1/(√8 + √9).", "o": ["2", "3", "√9 − 1", "1"], "a": 0, "e": "Каждое слагаемое равно √(k+1) − √k; сумма = √9 − 1 = 2."}, {"q": "Докажите, что √2 + √3 иррационально. Что получится при возведении в квадрат?", "o": ["5 + 2√6 — иррационально, значит и исходное число", "5 — рационально", "6", "√5"], "a": 0, "e": "Если бы √2 + √3 было рациональным, то и его квадрат 5 + 2√6 был бы рациональным."}, {"q": "Найдите √(7 − 4√3).", "o": ["2 − √3", "√3 − 2", "4 − √3", "√7 − 2"], "a": 0, "e": "(2 − √3)² = 7 − 4√3, и 2 − √3 > 0."}]}}]}, {"title": "Квадратные уравнения", "topics": [{"id": "a8-quad-eq", "title": "Квадратные уравнения. Дискриминант", "explain": "Квадратное уравнение: ax² + bx + c = 0 (a ≠ 0). Дискриминант D = b² − 4ac определяет число корней: D > 0 — два корня, D = 0 — один, D < 0 — нет действительных корней. Неполные уравнения (b = 0 или c = 0) удобнее решать разложением на множители.", "formula": "D = b² − 4ac;  x = (−b ± √D) / (2a)", "levels": {"easy": [{"q": "Решите x² = 16.", "o": ["−4 и 4", "4", "8", "−4"], "a": 0, "e": "Не забываем отрицательный корень."}, {"q": "Дискриминант уравнения x² − 5x + 6 = 0?", "o": ["1", "49", "−1", "25"], "a": 0, "e": "25 − 24 = 1."}, {"q": "Сколько корней, если D < 0?", "o": ["нет действительных корней", "один", "два", "бесконечно много"], "a": 0, "e": "Корень из отрицательного числа не извлекается."}], "medium": [{"q": "Решите x² − 5x + 6 = 0.", "o": ["2 и 3", "−2 и −3", "1 и 6", "−1 и 6"], "a": 0, "e": "x = (5 ± 1)/2."}, {"q": "Решите 2x² − 8x = 0.", "o": ["0 и 4", "4", "0 и −4", "2 и 4"], "a": 0, "e": "2x(x − 4) = 0."}, {"q": "Решите x² + 4x + 4 = 0.", "o": ["−2", "2", "−2 и 2", "нет корней"], "a": 0, "e": "(x + 2)² = 0."}], "hard": [{"q": "Решите 3x² + 2x − 1 = 0.", "o": ["1/3 и −1", "−1/3 и 1", "1 и 3", "нет корней"], "a": 0, "e": "D = 4 + 12 = 16; x = (−2 ± 4)/6."}, {"q": "При каком c уравнение x² − 6x + c = 0 имеет один корень?", "o": ["9", "36", "6", "−9"], "a": 0, "e": "D = 36 − 4c = 0."}, {"q": "Площадь прямоугольника 48 см², одна сторона на 2 см больше другой. Меньшая сторона?", "o": ["6 см", "8 см", "4 см", "12 см"], "a": 0, "e": "x(x + 2) = 48 → x² + 2x − 48 = 0 → x = 6."}], "olympiad": [{"q": "При каких a уравнение x² + ax + 4 = 0 не имеет корней?", "o": ["−4 < a < 4", "a > 4", "a < −4", "при любом a"], "a": 0, "e": "D = a² − 16 < 0."}, {"q": "Решите x⁴ − 5x² + 4 = 0.", "o": ["±1 и ±2", "1 и 4", "±1", "±2"], "a": 0, "e": "Замена t = x²: t² − 5t + 4 = 0, t = 1 или 4."}, {"q": "Решите (x² − 3x)² − 2(x² − 3x) − 8 = 0.", "o": ["−1, 1, 2, 4", "1 и 2", "4 и −1", "нет корней"], "a": 0, "e": "t = x² − 3x: t = 4 → x = 4, −1; t = −2 → x = 1, 2."}]}}, {"id": "a8-vieta", "title": "Теорема Виета", "explain": "Теорема Виета: если x₁ и x₂ — корни приведённого квадратного уравнения x² + px + q = 0, то их сумма равна −p, а произведение равно q. Для уравнения ax² + bx + c = 0: x₁ + x₂ = −b/a, x₁·x₂ = c/a. Обратная теорема позволяет подбирать корни устно и составлять уравнение по корням.", "formula": "x₁ + x₂ = −p;  x₁·x₂ = q", "levels": {"easy": [{"q": "Сумма корней уравнения x² − 7x + 10 = 0?", "o": ["7", "−7", "10", "−10"], "a": 0, "e": "x₁ + x₂ = −p = 7."}, {"q": "Произведение корней x² + 3x − 4 = 0?", "o": ["−4", "3", "4", "−3"], "a": 0, "e": "x₁x₂ = q."}, {"q": "Подберите корни x² − 5x + 4 = 0.", "o": ["1 и 4", "2 и 2", "−1 и −4", "5 и 4"], "a": 0, "e": "Сумма 5, произведение 4."}], "medium": [{"q": "Составьте уравнение с корнями 2 и −5.", "o": ["x² + 3x − 10 = 0", "x² − 3x − 10 = 0", "x² + 3x + 10 = 0", "x² − 7x + 10 = 0"], "a": 0, "e": "p = −(2 − 5) = 3, q = −10."}, {"q": "Один корень x² − 8x + q = 0 равен 3. Найдите q.", "o": ["15", "5", "24", "−15"], "a": 0, "e": "Второй корень 5, q = 3·5."}, {"q": "Сумма корней 2x² − 6x + 1 = 0?", "o": ["3", "6", "−3", "1/2"], "a": 0, "e": "−b/a = 6/2."}], "hard": [{"q": "x₁, x₂ — корни x² − 4x + 1 = 0. Найдите x₁² + x₂².", "o": ["14", "16", "18", "2"], "a": 0, "e": "(x₁ + x₂)² − 2x₁x₂ = 16 − 2."}, {"q": "Найдите 1/x₁ + 1/x₂ для x² − 6x + 2 = 0.", "o": ["3", "1/3", "6", "1/2"], "a": 0, "e": "(x₁ + x₂)/(x₁x₂) = 6/2."}, {"q": "Корни уравнения x² + px + 12 = 0 отличаются на 1. Найдите p (p < 0).", "o": ["−7", "−1", "−12", "7"], "a": 0, "e": "Корни 3 и 4 — сумма 7, p = −7."}], "olympiad": [{"q": "Для x² − 3x − 5 = 0 найдите x₁³ + x₂³.", "o": ["72", "27", "−18", "42"], "a": 0, "e": "(x₁+x₂)³ − 3x₁x₂(x₁+x₂) = 27 + 45 = 72."}, {"q": "При каком a сумма квадратов корней x² − ax + a − 1 = 0 минимальна?", "o": ["a = 1", "a = 0", "a = 2", "a = −1"], "a": 0, "e": "x₁² + x₂² = a² − 2a + 2 = (a − 1)² + 1."}, {"q": "Корни x² + px + q = 0 равны p и q (p, q ≠ 0). Найдите p и q.", "o": ["p = 1, q = −2", "p = −1, q = 2", "p = 2, q = 1", "p = q = 1"], "a": 0, "e": "p + q = −p, pq = q → p = 1, q = −2."}]}}, {"id": "a8-rational-eq", "title": "Дробно-рациональные уравнения", "explain": "Дробно-рациональное уравнение содержит переменную в знаменателе. Его решают так: находят общий знаменатель, умножают на него обе части, решают полученное целое уравнение и обязательно проверяют, не обращают ли найденные корни знаменатель в ноль (такие «корни» — посторонние). С помощью таких уравнений решают задачи на движение и совместную работу.", "levels": {"easy": [{"q": "Решите 6/x = 2.", "o": ["3", "12", "1/3", "4"], "a": 0, "e": "x = 6/2."}, {"q": "Какие значения x недопустимы в уравнении 1/(x − 2) = 5?", "o": ["x = 2", "x = 5", "x = 0", "x = −2"], "a": 0, "e": "Знаменатель не равен нулю."}, {"q": "Решите (x − 3)/x = 0.", "o": ["3", "0", "0 и 3", "нет корней"], "a": 0, "e": "Числитель равен нулю, знаменатель — нет."}], "medium": [{"q": "Решите x/(x − 1) = 2.", "o": ["2", "1", "−2", "нет корней"], "a": 0, "e": "x = 2x − 2."}, {"q": "Решите (x² − 4)/(x − 2) = 0.", "o": ["−2", "2", "±2", "нет корней"], "a": 0, "e": "x = 2 — посторонний корень."}, {"q": "Решите 3/x + 1 = 4/x.", "o": ["1", "−1", "7", "нет корней"], "a": 0, "e": "3 + x = 4."}], "hard": [{"q": "Решите 2/(x − 1) = 1.", "o": ["3", "1", "2", "−1"], "a": 0, "e": "x − 1 = 2, x = 3; знаменатель при этом не равен нулю."}, {"q": "Лодка прошла 12 км по течению и 12 км против за 5 ч. Скорость течения 1 км/ч. Собственная скорость?", "o": ["5 км/ч", "4 км/ч", "6 км/ч", "3 км/ч"], "a": 0, "e": "12/(v+1) + 12/(v−1) = 5 → 5v² − 24v − 5 = 0 → v = 5."}, {"q": "Решите x/(x + 2) − 2/(x − 2) = 8/(x² − 4).", "o": ["6", "−2", "6 и −2", "2"], "a": 0, "e": "x(x − 2) − 2(x + 2) = 8 → x² − 4x − 12 = 0 → x = 6 или −2 (посторонний)."}], "olympiad": [{"q": "Решите x + 1/x = 5/2.", "o": ["2 и 1/2", "2", "1/2", "нет корней"], "a": 0, "e": "2x² − 5x + 2 = 0."}, {"q": "Двое рабочих вместе делают работу за 6 дней. Первый один — на 5 дней быстрее второго. За сколько дней сделает работу первый?", "o": ["10", "15", "12", "8"], "a": 0, "e": "1/x + 1/(x + 5) = 1/6 → x² − 7x − 30 = 0 → x = 10."}, {"q": "Решите (x² + 1)/x + x/(x² + 1) = 5/2.", "o": ["1", "2 и 1/2", "нет корней", "−1"], "a": 0, "e": "t = (x² + 1)/x: t + 1/t = 5/2 → t = 2 или 1/2; x² − 2x + 1 = 0 → x = 1; x² − x/2 + 1 = 0 — корней нет."}]}}]}, {"title": "Квадратичная функция", "topics": [{"id": "a8-quad-fn", "title": "Квадратичная функция и её график", "explain": "Квадратичная функция: y = ax² + bx + c (a ≠ 0), её график — парабола. При a > 0 ветви направлены вверх, при a < 0 — вниз. Вершина параболы имеет абсциссу x₀ = −b/(2a), ось симметрии — прямая x = x₀. Точки пересечения с осью Ox — корни уравнения ax² + bx + c = 0, с осью Oy — точка (0; c).", "formula": "x₀ = −b / (2a);  y₀ = y(x₀)", "levels": {"easy": [{"q": "Куда направлены ветви параболы y = −2x² + 3?", "o": ["вниз", "вверх", "вправо", "влево"], "a": 0, "e": "a < 0."}, {"q": "Вершина параболы y = x²?", "o": ["(0; 0)", "(1; 1)", "(0; 1)", "(1; 0)"], "a": 0, "e": "Простейшая парабола."}, {"q": "Где парабола y = x² − 3x + 5 пересекает ось Oy?", "o": ["(0; 5)", "(5; 0)", "(0; −3)", "(3; 0)"], "a": 0, "e": "При x = 0 y = c."}], "medium": [{"q": "Абсцисса вершины y = x² − 6x + 1?", "o": ["3", "−3", "6", "1"], "a": 0, "e": "x₀ = 6/2."}, {"q": "Вершина параболы y = (x − 2)² + 3?", "o": ["(2; 3)", "(−2; 3)", "(2; −3)", "(3; 2)"], "a": 0, "e": "Сдвиг на 2 вправо и на 3 вверх."}, {"q": "Наименьшее значение y = x² + 4x + 7?", "o": ["3", "7", "−2", "4"], "a": 0, "e": "x₀ = −2, y = 4 − 8 + 7 = 3."}], "hard": [{"q": "Нули функции y = x² − x − 12?", "o": ["−3 и 4", "3 и −4", "−3 и −4", "нет нулей"], "a": 0, "e": "Корни уравнения: D = 49."}, {"q": "На каком промежутке возрастает y = −x² + 4x?", "o": ["(−∞; 2]", "[2; +∞)", "(−∞; +∞)", "[0; 4]"], "a": 0, "e": "Ветви вниз, вершина x = 2: слева от неё возрастает."}, {"q": "Наибольшее значение y = −2x² + 8x − 3?", "o": ["5", "−3", "8", "2"], "a": 0, "e": "x₀ = 2: −8 + 16 − 3 = 5."}], "olympiad": [{"q": "При каком c вершина параболы y = x² − 4x + c лежит на оси Ox?", "o": ["4", "0", "−4", "2"], "a": 0, "e": "y₀ = 4 − 8 + c = 0."}, {"q": "Найдите наибольшую площадь прямоугольника с периметром 20.", "o": ["25", "20", "100", "24"], "a": 0, "e": "S = x(10 − x), максимум при x = 5."}, {"q": "Парабола y = ax² + bx + c проходит через (0; 1), (1; 0), (2; 1). Найдите a.", "o": ["1", "−1", "2", "1/2"], "a": 0, "e": "c = 1; a + b = −1; 4a + 2b = 0 → b = −2a → a = 1."}]}}]}, {"title": "Неравенства", "topics": [{"id": "a8-ineq", "title": "Линейные неравенства и системы неравенств", "explain": "Неравенство решают почти как уравнение, но при умножении или делении обеих частей на отрицательное число знак неравенства меняется на противоположный. Решение записывают промежутком. Решение системы неравенств — пересечение решений каждого неравенства.", "formula": "Если a < b и c < 0, то ac > bc", "levels": {"easy": [{"q": "Решите x + 3 > 5.", "o": ["x > 2", "x > 8", "x < 2", "x > −2"], "a": 0, "e": "x > 5 − 3."}, {"q": "Решите −2x < 6.", "o": ["x > −3", "x < −3", "x > 3", "x < 3"], "a": 0, "e": "Делим на −2 и меняем знак."}, {"q": "Запишите промежутком x ≥ 4.", "o": ["[4; +∞)", "(4; +∞)", "(−∞; 4]", "[4; 4]"], "a": 0, "e": "Квадратная скобка — граница включена."}], "medium": [{"q": "Решите 3x − 7 ≤ 2.", "o": ["x ≤ 3", "x ≥ 3", "x ≤ −3", "x < 3"], "a": 0, "e": "3x ≤ 9."}, {"q": "Решите систему x > 1, x < 5.", "o": ["(1; 5)", "[1; 5]", "x > 5", "нет решений"], "a": 0, "e": "Пересечение промежутков."}, {"q": "Наименьшее целое решение 2x + 1 > 7?", "o": ["4", "3", "6", "−3"], "a": 0, "e": "x > 3."}], "hard": [{"q": "Решите систему 2x − 1 ≥ 3, 5 − x > 0.", "o": ["[2; 5)", "(2; 5]", "x ≥ 2", "нет решений"], "a": 0, "e": "x ≥ 2 и x < 5."}, {"q": "Решите (x − 1)/2 − (x + 1)/3 < 1.", "o": ["x < 11", "x > 11", "x < 5", "x < −1"], "a": 0, "e": "3x − 3 − 2x − 2 < 6."}, {"q": "Сколько целых решений у системы −3 < 2x + 1 ≤ 7?", "o": ["5", "4", "3", "6"], "a": 0, "e": "−4 < 2x ≤ 6 → −2 < x ≤ 3: целые −1, 0, 1, 2, 3."}], "olympiad": [{"q": "При каких a неравенство ax > 3 имеет решения x > 3/a?", "o": ["a > 0", "a < 0", "a = 0", "при любом a"], "a": 0, "e": "Делим на положительное число — знак сохраняется."}, {"q": "Решите |2x − 3| < 5.", "o": ["(−1; 4)", "(−4; 1)", "x < 4", "(−1; 1)"], "a": 0, "e": "−5 < 2x − 3 < 5 → −2 < 2x < 8."}, {"q": "Решите систему x ≥ 3, x ≤ 3, x ≠ 3.", "o": ["нет решений", "x = 3", "[3; +∞)", "любое x"], "a": 0, "e": "Первые два условия дают x = 3, третье его исключает."}]}}, {"id": "a8-quad-ineq", "title": "Квадратные неравенства. Метод интервалов", "explain": "Квадратное неравенство ax² + bx + c > 0 (или <, ≥, ≤) решают с помощью параболы: находят корни, отмечают их на оси и смотрят, где парабола выше или ниже оси. Метод интервалов: отмечают нули выражения, определяют знак на каждом промежутке и выбирают нужные.", "levels": {"easy": [{"q": "Решите x² < 9.", "o": ["(−3; 3)", "x < 3", "x < ±3", "(−∞; −3) ∪ (3; +∞)"], "a": 0, "e": "Парабола y = x² − 9 ниже оси между корнями."}, {"q": "Решите x² > 0.", "o": ["x ≠ 0", "x > 0", "любое x", "нет решений"], "a": 0, "e": "Квадрат положителен при всех x, кроме нуля."}, {"q": "Решите x² + 1 < 0.", "o": ["нет решений", "любое x", "x < −1", "x = 0"], "a": 0, "e": "x² + 1 ≥ 1 > 0."}], "medium": [{"q": "Решите x² − 5x + 6 < 0.", "o": ["(2; 3)", "(−∞; 2) ∪ (3; +∞)", "[2; 3]", "(−3; −2)"], "a": 0, "e": "Корни 2 и 3, ветви вверх."}, {"q": "Решите x² − 4x ≥ 0.", "o": ["(−∞; 0] ∪ [4; +∞)", "[0; 4]", "x ≥ 4", "x ≥ 0"], "a": 0, "e": "Корни 0 и 4."}, {"q": "Решите (x − 1)(x + 2) > 0.", "o": ["(−∞; −2) ∪ (1; +∞)", "(−2; 1)", "x > 1", "x > −2"], "a": 0, "e": "Метод интервалов."}], "hard": [{"q": "Решите −x² + 2x + 3 ≥ 0.", "o": ["[−1; 3]", "(−∞; −1] ∪ [3; +∞)", "(−1; 3)", "[1; 3]"], "a": 0, "e": "Умножим на −1: x² − 2x − 3 ≤ 0."}, {"q": "Решите (x − 2)/(x + 3) ≤ 0.", "o": ["(−3; 2]", "[−3; 2]", "(−∞; −3) ∪ [2; +∞)", "(−3; 2)"], "a": 0, "e": "x = −3 исключаем — знаменатель."}, {"q": "Найдите область определения √(x² − 9).", "o": ["(−∞; −3] ∪ [3; +∞)", "[−3; 3]", "x ≥ 3", "x ≥ 9"], "a": 0, "e": "x² − 9 ≥ 0."}], "olympiad": [{"q": "При каких m неравенство x² + mx + 9 > 0 верно при всех x?", "o": ["−6 < m < 6", "m > 6", "m < 6", "при любом m"], "a": 0, "e": "D = m² − 36 < 0."}, {"q": "Решите (x − 1)²(x − 3) < 0.", "o": ["x < 3, x ≠ 1", "x < 3", "(1; 3)", "x < 1"], "a": 0, "e": "Множитель (x − 1)² не меняет знак, но обращает выражение в 0 при x = 1."}, {"q": "Решите x(x − 2)(x + 4) > 0.", "o": ["(−4; 0) ∪ (2; +∞)", "(0; 2)", "(−∞; −4) ∪ (0; 2)", "x > 2"], "a": 0, "e": "Нули −4, 0, 2; на крайнем правом промежутке знак «+», дальше чередуется."}]}}]}, {"title": "Элементы теории вероятностей", "topics": [{"id": "a8-prob", "title": "Случайные события. Классическая вероятность", "explain": "Случайное событие может произойти или не произойти. Вероятность события в классической модели — отношение числа благоприятных исходов к числу всех равновозможных исходов. Вероятность лежит от 0 (невозможное событие) до 1 (достоверное). Вероятность противоположного события равна 1 − P(A).", "formula": "P(A) = m / n;  P(Ā) = 1 − P(A)", "check": true, "levels": {"easy": [{"q": "Вероятность выпадения «орла» у монеты?", "o": ["1/2", "1", "0", "1/3"], "a": 0, "e": "Два равновозможных исхода."}, {"q": "Вероятность выпадения 7 на обычном кубике?", "o": ["0", "1/6", "1/7", "1"], "a": 0, "e": "Невозможное событие."}, {"q": "Вероятность выпадения чётного числа на кубике?", "o": ["1/2", "1/3", "1/6", "2/3"], "a": 0, "e": "2, 4, 6 — три из шести."}], "medium": [{"q": "В мешке 3 красных и 7 синих шаров. Вероятность достать красный?", "o": ["0,3", "0,7", "3/7", "0,5"], "a": 0, "e": "3/10."}, {"q": "Вероятность, что на кубике выпадет число больше 4?", "o": ["1/3", "1/2", "2/3", "1/6"], "a": 0, "e": "5 и 6 — два исхода из шести."}, {"q": "Вероятность дождя 0,35. Вероятность, что дождя не будет?", "o": ["0,65", "0,35", "0,5", "1,35"], "a": 0, "e": "1 − 0,35."}], "hard": [{"q": "Бросают две монеты. Вероятность двух «орлов»?", "o": ["1/4", "1/2", "1/3", "2/3"], "a": 0, "e": "Исходы: ОО, ОР, РО, РР."}, {"q": "Бросают два кубика. Вероятность, что сумма равна 7?", "o": ["1/6", "1/12", "7/36", "1/36"], "a": 0, "e": "6 благоприятных пар из 36."}, {"q": "Из 25 билетов ученик выучил 20. Вероятность вытянуть невыученный?", "o": ["0,2", "0,8", "0,25", "0,05"], "a": 0, "e": "5/25."}], "olympiad": [{"q": "Бросают три монеты. Вероятность хотя бы одного «орла»?", "o": ["7/8", "1/2", "3/8", "1/8"], "a": 0, "e": "1 − P(ни одного) = 1 − 1/8."}, {"q": "Бросают два кубика. Вероятность, что выпадут одинаковые числа?", "o": ["1/6", "1/36", "1/12", "1/3"], "a": 0, "e": "6 дублей из 36."}, {"q": "В классе 30 учеников. Почему вероятность совпадения дней рождения у двоих довольно велика (≈ 70%)?", "o": ["пар учеников очень много — 435", "в году мало дней", "все рождаются летом", "это неправда"], "a": 0, "e": "Парадокс дней рождения: считаем пары, а не одного ученика."}]}}]}]}, "9": {"sections": [{"title": "Уравнения и неравенства с двумя переменными", "topics": [{"id": "a9-systems", "title": "Системы уравнений второй степени", "explain": "В системах второй степени хотя бы одно уравнение содержит квадраты или произведение переменных. Основные методы: подстановка (выразить переменную из линейного уравнения), сложение уравнений, замена переменных (например, u = x + y, v = xy), графический метод (пересечение окружности, параболы, прямой).", "levels": {"easy": [{"q": "Является ли (1; 2) решением системы x² + y² = 5, x + y = 3?", "o": ["да", "нет", "только первого уравнения", "только второго"], "a": 0, "e": "1 + 4 = 5, 1 + 2 = 3."}, {"q": "Решите систему y = x², y = 4.", "o": ["(2; 4) и (−2; 4)", "(2; 4)", "(4; 2)", "(4; 16)"], "a": 0, "e": "x² = 4."}, {"q": "Что является графиком x² + y² = 9?", "o": ["окружность радиусом 3", "парабола", "прямая", "окружность радиусом 9"], "a": 0, "e": "Центр (0; 0), r = 3."}], "medium": [{"q": "Решите x + y = 5, xy = 6.", "o": ["(2; 3) и (3; 2)", "(1; 6)", "(2; 3)", "(−2; −3)"], "a": 0, "e": "По теореме Виета x и y — корни t² − 5t + 6 = 0."}, {"q": "Решите y = x + 1, x² + y = 7.", "o": ["(2; 3) и (−3; −2)", "(2; 3)", "(−2; −1)", "(3; 4)"], "a": 0, "e": "x² + x − 6 = 0."}, {"q": "Сколько решений у системы x² + y² = 4, y = 3?", "o": ["ни одного", "одно", "два", "четыре"], "a": 0, "e": "Прямая y = 3 не пересекает окружность радиуса 2."}], "hard": [{"q": "Решите x² − y² = 16, x − y = 2.", "o": ["(5; 3)", "(3; 5)", "(4; 0)", "(6; 4)"], "a": 0, "e": "(x − y)(x + y) = 16 → x + y = 8."}, {"q": "Сумма квадратов двух натуральных чисел 25, разность 1. Числа?", "o": ["3 и 4", "1 и 2", "4 и 5", "2 и 3"], "a": 0, "e": "9 + 16 = 25."}, {"q": "Периметр прямоугольника 14 см, площадь 12 см². Стороны?", "o": ["3 и 4 см", "2 и 6 см", "1 и 12 см", "2 и 5 см"], "a": 0, "e": "x + y = 7, xy = 12."}], "olympiad": [{"q": "Решите x² + y² = 13, xy = 6 (найдите все пары).", "o": ["(2;3), (3;2), (−2;−3), (−3;−2)", "(2;3), (3;2)", "(2;3)", "(−2;3), (3;−2)"], "a": 0, "e": "(x + y)² = 25 → x + y = ±5; xy = 6."}, {"q": "При каком r окружность x² + y² = r² касается прямой x + y = 2?", "o": ["√2", "2", "1", "4"], "a": 0, "e": "Расстояние от центра до прямой: 2/√2 = √2."}, {"q": "Сколько решений у системы y = x², x² + y² = 2?", "o": ["2", "4", "1", "0"], "a": 0, "e": "y² + y − 2 = 0 → y = 1 (y = −2 невозможно, т. к. y = x² ≥ 0); x = ±1."}]}}, {"id": "a9-ineq2", "title": "Неравенства с двумя переменными и их системы", "explain": "Решение неравенства с двумя переменными — множество точек плоскости. Сначала строят границу (прямую, параболу, окружность), затем выбирают, какая из частей плоскости подходит: удобно подставить «пробную» точку. Для системы находят пересечение областей.", "check": true, "levels": {"easy": [{"q": "Принадлежит ли точка (0; 0) решениям y > x + 1?", "o": ["нет", "да", "только при x = 0", "нельзя сказать"], "a": 0, "e": "0 > 1 — неверно."}, {"q": "Что задаёт неравенство x² + y² ≤ 16?", "o": ["круг радиусом 4 вместе с границей", "окружность", "внешность круга", "квадрат"], "a": 0, "e": "Все точки на расстоянии не больше 4 от начала координат."}, {"q": "Что задаёт неравенство y ≥ 0?", "o": ["верхнюю полуплоскость с осью Ox", "ось Oy", "нижнюю полуплоскость", "точку"], "a": 0, "e": "Все точки с неотрицательной ординатой."}], "medium": [{"q": "Какая точка удовлетворяет y < x²?", "o": ["(2; 1)", "(1; 2)", "(0; 1)", "(0; 0)"], "a": 0, "e": "1 < 4 — верно."}, {"q": "Какая точка лежит внутри круга x² + y² < 9?", "o": ["(1; 2)", "(3; 1)", "(2; 3)", "(0; 3)"], "a": 0, "e": "1 + 4 = 5 < 9."}, {"q": "Неравенство x + y ≤ 4 задаёт полуплоскость…", "o": ["ниже прямой y = 4 − x, включая её", "выше этой прямой", "только прямую", "всю плоскость"], "a": 0, "e": "y ≤ 4 − x."}], "hard": [{"q": "Площадь фигуры, заданной системой x ≥ 0, y ≥ 0, x + y ≤ 4?", "o": ["8", "16", "4", "2"], "a": 0, "e": "Прямоугольный треугольник с катетами 4."}, {"q": "Площадь фигуры |x| + |y| ≤ 2?", "o": ["8", "4", "16", "2"], "a": 0, "e": "Квадрат с диагоналями 4: 4·4/2."}, {"q": "Сколько точек с целыми координатами удовлетворяет x² + y² ≤ 1?", "o": ["5", "4", "1", "9"], "a": 0, "e": "(0;0), (±1;0), (0;±1)."}], "olympiad": [{"q": "Площадь фигуры x² + y² ≤ 4, y ≥ 0?", "o": ["2π", "4π", "π", "8π"], "a": 0, "e": "Половина круга радиусом 2."}, {"q": "Площадь фигуры 1 ≤ x² + y² ≤ 4?", "o": ["3π", "4π", "π", "2π"], "a": 0, "e": "Кольцо: 4π − π."}, {"q": "Сколько целых точек в квадрате |x| ≤ 2, |y| ≤ 2?", "o": ["25", "16", "20", "9"], "a": 0, "e": "5 × 5."}]}}]}, {"title": "Последовательности", "topics": [{"id": "a9-sequences", "title": "Числовые последовательности", "explain": "Числовая последовательность — занумерованный ряд чисел a₁, a₂, a₃, … Её можно задать формулой n-го члена (aₙ = 2n + 1) или рекуррентно — через предыдущие члены (a₁ = 1, aₙ₊₁ = aₙ + 3). Последовательность возрастает, если каждый член больше предыдущего, и убывает, если меньше.", "levels": {"easy": [{"q": "Пятый член последовательности aₙ = 3n − 1?", "o": ["14", "15", "12", "16"], "a": 0, "e": "3·5 − 1."}, {"q": "Следующий член: 2, 4, 8, 16, …", "o": ["32", "24", "20", "18"], "a": 0, "e": "Каждый член вдвое больше."}, {"q": "Последовательность aₙ = 10 − n…", "o": ["убывающая", "возрастающая", "постоянная", "ни та ни другая"], "a": 0, "e": "Каждый следующий член на 1 меньше."}], "medium": [{"q": "a₁ = 2, aₙ₊₁ = 3aₙ − 1. Найдите a₃.", "o": ["14", "5", "17", "8"], "a": 0, "e": "a₂ = 5, a₃ = 14."}, {"q": "Какой номер у члена 47 в aₙ = 5n + 2?", "o": ["9", "10", "8", "11"], "a": 0, "e": "5n + 2 = 47."}, {"q": "Последовательность Фибоначчи 1, 1, 2, 3, 5, 8, … Следующий член?", "o": ["13", "11", "10", "16"], "a": 0, "e": "5 + 8."}], "hard": [{"q": "Является ли 100 членом aₙ = n² + n?", "o": ["нет", "да, при n = 9", "да, при n = 10", "да, при n = 99"], "a": 0, "e": "n² + n = 100 не имеет натуральных корней (9·10 = 90, 10·11 = 110)."}, {"q": "Сколько отрицательных членов в aₙ = 2n − 15?", "o": ["7", "8", "15", "6"], "a": 0, "e": "2n < 15 → n ≤ 7."}, {"q": "Найдите формулу n-го члена: 1, 4, 9, 16, …", "o": ["n²", "3n − 2", "2n − 1", "n + 3"], "a": 0, "e": "Квадраты натуральных чисел."}], "olympiad": [{"q": "Найдите наименьший член последовательности aₙ = n² − 8n + 5.", "o": ["−11", "5", "−16", "−12"], "a": 0, "e": "При n = 4: 16 − 32 + 5."}, {"q": "a₁ = 1, aₙ₊₁ = aₙ + 2n + 1. Найдите a₁₀.", "o": ["100", "91", "110", "81"], "a": 0, "e": "Это квадраты: aₙ = n²."}, {"q": "Найдите формулу: 1/2, 2/3, 3/4, 4/5, …", "o": ["n/(n + 1)", "(n + 1)/n", "1/n", "n/2"], "a": 0, "e": "Числитель — номер, знаменатель на 1 больше."}]}}, {"id": "a9-arith", "title": "Арифметическая прогрессия", "explain": "Арифметическая прогрессия — последовательность, в которой каждый член, начиная со второго, равен предыдущему, сложенному с одним и тем же числом d (разность прогрессии). Каждый член (кроме первого) — среднее арифметическое соседних. Сумму первых n членов можно найти по формуле, которую, по преданию, в детстве открыл Гаусс.", "formula": "aₙ = a₁ + (n − 1)d;  Sₙ = (a₁ + aₙ)·n/2 = (2a₁ + (n − 1)d)·n/2", "levels": {"easy": [{"q": "Разность прогрессии 3, 7, 11, 15, …?", "o": ["4", "3", "7", "−4"], "a": 0, "e": "7 − 3."}, {"q": "a₁ = 5, d = 2. Найдите a₄.", "o": ["11", "13", "9", "8"], "a": 0, "e": "5 + 3·2."}, {"q": "Является ли 5, 5, 5, … арифметической прогрессией?", "o": ["да, d = 0", "нет", "только при n = 1", "это геометрическая только"], "a": 0, "e": "Разность может быть нулём."}], "medium": [{"q": "Сумма 1 + 2 + … + 100?", "o": ["5050", "5000", "10 100", "4950"], "a": 0, "e": "(1 + 100)·100/2."}, {"q": "a₁ = 2, a₁₀ = 29. Найдите d.", "o": ["3", "2,7", "27", "4"], "a": 0, "e": "29 = 2 + 9d."}, {"q": "a₃ = 8, a₅ = 14. Найдите a₄.", "o": ["11", "10", "12", "22"], "a": 0, "e": "Среднее соседних."}], "hard": [{"q": "Сумма первых 10 членов: a₁ = 3, d = 4.", "o": ["210", "190", "230", "40"], "a": 0, "e": "S = (6 + 36)·10/2."}, {"q": "Сумма всех двузначных чисел?", "o": ["4905", "4950", "5050", "4500"], "a": 0, "e": "(10 + 99)·90/2."}, {"q": "Сколько членов прогрессии 2, 5, 8, … меньше 100?", "o": ["33", "32", "34", "99"], "a": 0, "e": "2 + 3(n − 1) < 100 → n < 33,67."}], "olympiad": [{"q": "a₂ + a₉ = 20. Найдите S₁₀.", "o": ["100", "200", "110", "90"], "a": 0, "e": "a₁ + a₁₀ = a₂ + a₉ = 20; S₁₀ = 20·10/2."}, {"q": "Углы треугольника образуют арифметическую прогрессию. Чему обязательно равен один из углов?", "o": ["60°", "90°", "45°", "30°"], "a": 0, "e": "Средний угол a, сумма 3a = 180°."}, {"q": "Сумма первых n нечётных чисел равна…", "o": ["n²", "2n", "n(n + 1)", "2n − 1"], "a": 0, "e": "1 + 3 + … + (2n − 1) = n²."}]}}, {"id": "a9-geom", "title": "Геометрическая прогрессия", "explain": "Геометрическая прогрессия — последовательность ненулевых чисел, в которой каждый член, начиная со второго, равен предыдущему, умноженному на одно и то же число q (знаменатель). Если |q| < 1, прогрессия бесконечно убывающая, и её сумма конечна: S = b₁/(1 − q). Так растут вклады со сложными процентами и размножаются бактерии.", "formula": "bₙ = b₁·qⁿ⁻¹;  Sₙ = b₁(qⁿ − 1)/(q − 1);  S = b₁/(1 − q) при |q| < 1", "levels": {"easy": [{"q": "Знаменатель прогрессии 3, 6, 12, 24, …?", "o": ["2", "3", "6", "1/2"], "a": 0, "e": "6 : 3."}, {"q": "b₁ = 2, q = 3. Найдите b₃.", "o": ["18", "54", "8", "12"], "a": 0, "e": "2·3²."}, {"q": "Может ли член геометрической прогрессии быть нулём?", "o": ["нет", "да", "только первый", "только при q = 1"], "a": 0, "e": "По определению члены ненулевые."}], "medium": [{"q": "Найдите b₅: 1, 2, 4, …", "o": ["16", "8", "32", "10"], "a": 0, "e": "2⁴."}, {"q": "Сумма 1 + 2 + 4 + … + 512?", "o": ["1023", "1024", "511", "1022"], "a": 0, "e": "2¹⁰ − 1."}, {"q": "b₂ = 6, b₄ = 54 (q > 0). Найдите b₃.", "o": ["18", "30", "27", "24"], "a": 0, "e": "b₃² = b₂·b₄ = 324."}], "hard": [{"q": "Сумма бесконечно убывающей прогрессии 1 + 1/2 + 1/4 + …?", "o": ["2", "1", "∞", "3/2"], "a": 0, "e": "1/(1 − 1/2)."}, {"q": "Запишите 0,(3) обыкновенной дробью.", "o": ["1/3", "3/10", "3/9 + 1", "33/100"], "a": 0, "e": "0,3 + 0,03 + … = 0,3/(1 − 0,1)."}, {"q": "Число бактерий удваивается каждый час. Было 100. Сколько через 5 ч?", "o": ["3200", "1000", "500", "1600"], "a": 0, "e": "100·2⁵."}], "olympiad": [{"q": "Вклад 100 000 ₸ под 10% годовых (сложные проценты). Сколько будет через 3 года?", "o": ["133 100 ₸", "130 000 ₸", "131 000 ₸", "133 000 ₸"], "a": 0, "e": "100 000·1,1³."}, {"q": "Запишите 0,(27) обыкновенной дробью.", "o": ["3/11", "27/100", "27/90", "1/27"], "a": 0, "e": "27/99 = 3/11."}, {"q": "Сумма бесконечной прогрессии 3, −1, 1/3, …?", "o": ["9/4", "3/2", "4", "2"], "a": 0, "e": "q = −1/3; 3/(1 + 1/3)."}]}}]}, {"title": "Тригонометрия", "topics": [{"id": "a9-radian", "title": "Радианная мера угла. Единичная окружность", "explain": "Угол можно измерять в градусах и радианах. 1 радиан — центральный угол, опирающийся на дугу, длина которой равна радиусу. Полный оборот 360° = 2π радиан, значит 180° = π. На единичной окружности (радиус 1) каждому углу соответствует точка; её абсцисса — косинус угла, ордината — синус.", "formula": "π рад = 180°;  α(рад) = α° · π / 180", "levels": {"easy": [{"q": "Сколько радиан в 180°?", "o": ["π", "2π", "π/2", "180"], "a": 0, "e": "Основное соотношение."}, {"q": "Переведите 90° в радианы.", "o": ["π/2", "π", "π/4", "2π"], "a": 0, "e": "90·π/180."}, {"q": "Переведите π/3 в градусы.", "o": ["60°", "30°", "120°", "90°"], "a": 0, "e": "180°/3."}], "medium": [{"q": "Переведите 135° в радианы.", "o": ["3π/4", "2π/3", "5π/6", "3π/2"], "a": 0, "e": "135·π/180 = 3π/4."}, {"q": "Сколько градусов в 1 радиане (примерно)?", "o": ["57°", "1°", "180°", "3,14°"], "a": 0, "e": "180/π ≈ 57,3°."}, {"q": "Длина дуги окружности радиусом 2 с углом π/2?", "o": ["π", "2π", "π/2", "4"], "a": 0, "e": "l = R·α = 2·π/2."}], "hard": [{"q": "В какой четверти лежит угол 5π/4?", "o": ["в III", "во II", "в IV", "в I"], "a": 0, "e": "5π/4 = 225°."}, {"q": "Координаты точки единичной окружности для угла π/2?", "o": ["(0; 1)", "(1; 0)", "(−1; 0)", "(0; −1)"], "a": 0, "e": "cos 90° = 0, sin 90° = 1."}, {"q": "Угол −π/6 в градусах?", "o": ["−30°", "330°", "30°", "−60°"], "a": 0, "e": "Отрицательный угол — поворот по часовой стрелке (−30° и 330° задают одну точку)."}], "olympiad": [{"q": "Сколько полных оборотов в угле 25π/3?", "o": ["4", "8", "3", "12"], "a": 0, "e": "25π/3 = 8π + π/3; 8π = 4 оборота."}, {"q": "На какой угол поворачивается минутная стрелка за 20 мин (в радианах)?", "o": ["2π/3", "π/3", "π/6", "π"], "a": 0, "e": "20 мин — треть оборота."}, {"q": "Площадь сектора радиусом 6 с углом π/3?", "o": ["6π", "12π", "3π", "2π"], "a": 0, "e": "S = R²α/2 = 36·π/6."}]}}, {"id": "a9-trig-def", "title": "Синус, косинус, тангенс, котангенс любого угла", "explain": "Для угла α на единичной окружности: cos α — абсцисса точки, sin α — ордината, tg α = sin α / cos α, ctg α = cos α / sin α. Значения синуса и косинуса лежат от −1 до 1. Знаки зависят от четверти: в I все положительны, во II положителен только синус, в III — тангенс и котангенс, в IV — косинус.", "formula": "sin 30° = 1/2;  cos 30° = √3/2;  sin 45° = cos 45° = √2/2;  tg 45° = 1;  sin 60° = √3/2", "levels": {"easy": [{"q": "sin 30° = ?", "o": ["1/2", "√3/2", "√2/2", "1"], "a": 0, "e": "Табличное значение."}, {"q": "cos 0° = ?", "o": ["1", "0", "−1", "1/2"], "a": 0, "e": "Точка (1; 0)."}, {"q": "tg 45° = ?", "o": ["1", "0", "√3", "√2/2"], "a": 0, "e": "sin 45° = cos 45°."}], "medium": [{"q": "Знак sin 150°?", "o": ["+", "−", "0", "не определён"], "a": 0, "e": "II четверть — синус положителен."}, {"q": "cos 180° = ?", "o": ["−1", "0", "1", "1/2"], "a": 0, "e": "Точка (−1; 0)."}, {"q": "tg 90° = ?", "o": ["не существует", "0", "1", "∞ = 1"], "a": 0, "e": "cos 90° = 0, делить нельзя."}], "hard": [{"q": "Вычислите sin² 60° + cos² 60°.", "o": ["1", "1/2", "3/4", "√3"], "a": 0, "e": "Основное тождество."}, {"q": "Знак tg 200°?", "o": ["+", "−", "0", "не определён"], "a": 0, "e": "III четверть — тангенс положителен."}, {"q": "Наибольшее значение 3 − 2sin α?", "o": ["5", "3", "1", "−5"], "a": 0, "e": "При sin α = −1."}], "olympiad": [{"q": "Вычислите sin 1° · sin 2° · … · sin 180°.", "o": ["0", "1", "1/2", "−1"], "a": 0, "e": "Среди множителей sin 180° = 0."}, {"q": "Найдите область значений y = sin α + cos α.", "o": ["[−√2; √2]", "[−2; 2]", "[−1; 1]", "[0; 2]"], "a": 0, "e": "sin α + cos α = √2·sin(α + 45°)."}, {"q": "Вычислите tg 1° · tg 2° · … · tg 89°.", "o": ["1", "0", "89", "√3"], "a": 0, "e": "tg α · tg(90° − α) = 1 — множители разбиваются на пары, tg 45° = 1."}]}}, {"id": "a9-identities", "title": "Основные тригонометрические тождества. Формулы приведения", "explain": "Основное тождество: sin²α + cos²α = 1. Из него следуют 1 + tg²α = 1/cos²α и tg α · ctg α = 1. Формулы приведения позволяют свести тригонометрические функции углов вида 90° ± α, 180° ± α, 270° ± α к функциям угла α: знак определяется по четверти исходного угла, а функция меняется на «кофункцию» при 90° и 270°.", "formula": "sin²α + cos²α = 1;  1 + tg²α = 1/cos²α;  sin(180° − α) = sin α;  cos(90° − α) = sin α", "levels": {"easy": [{"q": "Чему равно sin²α + cos²α?", "o": ["1", "0", "2", "sin 2α"], "a": 0, "e": "Основное тождество."}, {"q": "tg α · ctg α = ?", "o": ["1", "0", "tg²α", "−1"], "a": 0, "e": "Взаимно обратные."}, {"q": "sin(180° − α) = ?", "o": ["sin α", "−sin α", "cos α", "−cos α"], "a": 0, "e": "Формула приведения, II четверть."}], "medium": [{"q": "sin α = 3/5, α в I четверти. cos α = ?", "o": ["4/5", "−4/5", "2/5", "3/4"], "a": 0, "e": "√(1 − 9/25)."}, {"q": "cos(90° − α) = ?", "o": ["sin α", "cos α", "−sin α", "tg α"], "a": 0, "e": "Кофункция, I четверть."}, {"q": "Вычислите cos 120° с помощью формул приведения.", "o": ["−1/2", "1/2", "√3/2", "−√3/2"], "a": 0, "e": "cos(180° − 60°) = −cos 60°."}], "hard": [{"q": "tg α = 2. Найдите cos²α.", "o": ["1/5", "1/3", "4/5", "1/2"], "a": 0, "e": "1 + tg²α = 1/cos²α → cos²α = 1/5."}, {"q": "Упростите (1 − cos²α)/sin α.", "o": ["sin α", "cos α", "1", "tg α"], "a": 0, "e": "sin²α/sin α."}, {"q": "Вычислите sin 210°.", "o": ["−1/2", "1/2", "−√3/2", "√3/2"], "a": 0, "e": "sin(180° + 30°) = −sin 30°."}], "olympiad": [{"q": "sin α + cos α = 1/2. Найдите sin α · cos α.", "o": ["−3/8", "1/4", "3/8", "−1/4"], "a": 0, "e": "(sin α + cos α)² = 1 + 2 sin α cos α = 1/4."}, {"q": "Упростите sin⁴α − cos⁴α + cos²α.", "o": ["sin²α", "cos²α", "1", "0"], "a": 0, "e": "(sin²α − cos²α)·1 + cos²α."}, {"q": "Вычислите cos²1° + cos²2° + … + cos²89°.", "o": ["44,5", "45", "89", "44"], "a": 0, "e": "cos²α + cos²(90° − α) = 1: 44 пары и cos²45° = 1/2."}]}}, {"id": "a9-addition", "title": "Формулы сложения и двойного угла", "explain": "Формулы сложения выражают синус и косинус суммы и разности углов через функции этих углов. Частный случай — формулы двойного угла. С их помощью вычисляют значения для «нетабличных» углов (15°, 75°) и упрощают выражения.", "formula": "sin(α ± β) = sin α cos β ± cos α sin β;  cos(α ± β) = cos α cos β ∓ sin α sin β;  sin 2α = 2 sin α cos α;  cos 2α = cos²α − sin²α", "check": true, "levels": {"easy": [{"q": "sin 2α = ?", "o": ["2 sin α cos α", "2 sin α", "sin²α − cos²α", "sin α + cos α"], "a": 0, "e": "Формула двойного угла."}, {"q": "cos 2α = ?", "o": ["cos²α − sin²α", "2 cos α", "2 sin α cos α", "1 + cos α"], "a": 0, "e": "Формула двойного угла."}, {"q": "sin(α + β) = ?", "o": ["sin α cos β + cos α sin β", "sin α + sin β", "sin α sin β + cos α cos β", "cos α cos β − sin α sin β"], "a": 0, "e": "Формула синуса суммы."}], "medium": [{"q": "Вычислите 2 sin 15° cos 15°.", "o": ["1/2", "√3/2", "1", "1/4"], "a": 0, "e": "= sin 30°."}, {"q": "Вычислите cos² 15° − sin² 15°.", "o": ["√3/2", "1/2", "1", "√2/2"], "a": 0, "e": "= cos 30°."}, {"q": "Вычислите sin 75° через формулу сложения (45° + 30°).", "o": ["(√6 + √2)/4", "(√6 − √2)/4", "√3/2", "1"], "a": 0, "e": "√2/2·√3/2 + √2/2·1/2."}], "hard": [{"q": "sin α = 0,6, cos α = 0,8. Найдите sin 2α.", "o": ["0,96", "1,2", "0,48", "0,28"], "a": 0, "e": "2·0,6·0,8."}, {"q": "Для того же угла найдите cos 2α.", "o": ["0,28", "0,96", "−0,28", "0,2"], "a": 0, "e": "0,64 − 0,36."}, {"q": "Упростите cos 3α cos α − sin 3α sin α.", "o": ["cos 4α", "cos 2α", "sin 4α", "1"], "a": 0, "e": "cos(3α + α)."}], "olympiad": [{"q": "Вычислите cos 15°.", "o": ["(√6 + √2)/4", "(√6 − √2)/4", "√3/2", "1/2"], "a": 0, "e": "cos(45° − 30°) = √2/2·√3/2 + √2/2·1/2."}, {"q": "Вычислите tg 15°.", "o": ["2 − √3", "2 + √3", "√3 − 1", "1/√3"], "a": 0, "e": "tg(45° − 30°) = (1 − 1/√3)/(1 + 1/√3)."}, {"q": "Вычислите sin 18° · cos 36° (ответ — число).", "o": ["1/4", "1/2", "√5/4", "1/8"], "a": 0, "e": "Умножим и поделим на cos 18°: известный результат — 1/4."}]}}]}, {"title": "Комбинаторика и вероятность", "topics": [{"id": "a9-combinatorics", "title": "Элементы комбинаторики", "explain": "Комбинаторика отвечает на вопрос «сколькими способами?». Правило умножения: если первое действие можно выполнить m способами, а второе — n способами, то оба — m·n способами. Перестановки n элементов: n! Размещения из n по k (порядок важен) и сочетания из n по k (порядок не важен).", "formula": "Pₙ = n!;  Aₙᵏ = n!/(n − k)!;  Cₙᵏ = n!/(k!(n − k)!)", "levels": {"easy": [{"q": "Сколькими способами можно рассадить 3 человек на 3 стула?", "o": ["6", "3", "9", "27"], "a": 0, "e": "3! = 6."}, {"q": "5! = ?", "o": ["120", "25", "60", "720"], "a": 0, "e": "1·2·3·4·5."}, {"q": "3 футболки и 4 брюк. Сколько разных комплектов?", "o": ["12", "7", "34", "81"], "a": 0, "e": "Правило умножения."}], "medium": [{"q": "Сколькими способами выбрать старосту и заместителя из 10 учеников?", "o": ["90", "45", "100", "20"], "a": 0, "e": "A₁₀² = 10·9."}, {"q": "Сколькими способами выбрать 2 дежурных из 10?", "o": ["45", "90", "20", "100"], "a": 0, "e": "C₁₀² = 90/2."}, {"q": "Сколько трёхзначных чисел можно составить из цифр 1, 2, 3 без повторений?", "o": ["6", "27", "9", "3"], "a": 0, "e": "3!."}], "hard": [{"q": "Сколько трёхзначных чисел можно составить из цифр 0, 1, 2, 3 без повторений?", "o": ["18", "24", "12", "27"], "a": 0, "e": "Первая цифра — 3 способа (не 0), вторая — 3, третья — 2."}, {"q": "C₇³ = ?", "o": ["35", "210", "21", "42"], "a": 0, "e": "7·6·5/6."}, {"q": "Сколько диагоналей у шестиугольника?", "o": ["9", "6", "15", "12"], "a": 0, "e": "C₆² − 6 = 15 − 6."}], "olympiad": [{"q": "Сколькими способами можно переставить буквы слова «МАМА»?", "o": ["6", "24", "12", "4"], "a": 0, "e": "4!/(2!·2!)."}, {"q": "Сколько рукопожатий, если каждый из 20 человек пожал руку каждому?", "o": ["190", "400", "380", "200"], "a": 0, "e": "C₂₀² = 20·19/2."}, {"q": "Сколько путей из левого нижнего угла сетки 3×3 в правый верхний, двигаясь только вправо и вверх?", "o": ["20", "9", "6", "27"], "a": 0, "e": "Нужно 6 шагов, из них 3 вправо: C₆³."}]}}, {"id": "a9-probability", "title": "Вероятность. Сложение и умножение вероятностей", "explain": "Если события A и B несовместны, вероятность того, что произойдёт хотя бы одно из них, равна сумме вероятностей. Если события независимы, вероятность того, что произойдут оба, равна произведению вероятностей. Часто удобнее найти вероятность противоположного события и вычесть её из 1.", "formula": "P(A + B) = P(A) + P(B) (несовместные);  P(A·B) = P(A)·P(B) (независимые);  P(Ā) = 1 − P(A)", "levels": {"easy": [{"q": "Вероятность выпадения 1 или 2 на кубике?", "o": ["1/3", "1/6", "1/2", "2/3"], "a": 0, "e": "1/6 + 1/6."}, {"q": "Монету бросили дважды. Вероятность двух «решек»?", "o": ["1/4", "1/2", "1/3", "1"], "a": 0, "e": "1/2·1/2."}, {"q": "Стрелок попадает с вероятностью 0,9. Вероятность промаха?", "o": ["0,1", "0,9", "0,09", "0,5"], "a": 0, "e": "1 − 0,9."}], "medium": [{"q": "Два стрелка попадают с вероятностями 0,8 и 0,7. Вероятность, что попадут оба?", "o": ["0,56", "1,5", "0,75", "0,06"], "a": 0, "e": "0,8·0,7."}, {"q": "Для тех же стрелков: вероятность, что оба промахнутся?", "o": ["0,06", "0,56", "0,44", "0,3"], "a": 0, "e": "0,2·0,3."}, {"q": "Вероятность хотя бы одного попадания (0,8 и 0,7)?", "o": ["0,94", "0,56", "1,5", "0,06"], "a": 0, "e": "1 − 0,06."}], "hard": [{"q": "Из колоды 36 карт берут одну. Вероятность туза или короля?", "o": ["2/9", "1/9", "1/81", "1/18"], "a": 0, "e": "(4 + 4)/36."}, {"q": "Кубик бросают 3 раза. Вероятность, что ни разу не выпадет 6?", "o": ["125/216", "1/216", "1/2", "91/216"], "a": 0, "e": "(5/6)³."}, {"q": "В урне 4 белых и 6 чёрных. Достают 2 шара без возвращения. Вероятность, что оба белые?", "o": ["2/15", "4/25", "1/5", "6/45"], "a": 0, "e": "4/10·3/9."}], "olympiad": [{"q": "Вероятность хотя бы одной шестёрки при 4 бросках кубика (≈)?", "o": ["≈ 0,52", "≈ 0,67", "≈ 0,48", "4/6"], "a": 0, "e": "1 − (5/6)⁴ ≈ 1 − 0,482."}, {"q": "Студент знает 20 вопросов из 25. В билете 2 вопроса. Вероятность, что знает оба?", "o": ["19/30", "16/25", "4/5", "2/3"], "a": 0, "e": "20/25·19/24 = 380/600."}, {"q": "Почему игроку выгоднее в игре «Монти Холл» сменить дверь?", "o": ["вероятность выигрыша при смене 2/3, без смены 1/3", "вероятности равны 1/2", "смена уменьшает шанс", "нет разницы"], "a": 0, "e": "Ведущий открывает пустую дверь, зная, где приз."}]}}]}]}, "10": {"sections": [{"title": "Функции и их свойства", "topics": [{"id": "a10-functions", "title": "Функция и её свойства: область определения, чётность, периодичность", "explain": "Область определения D(f) — все x, при которых формула имеет смысл; область значений E(f) — все значения функции. Функция чётная, если f(−x) = f(x) (график симметричен относительно оси Oy), нечётная, если f(−x) = −f(x) (симметричен относительно начала координат). Периодическая функция повторяет значения через период T: f(x + T) = f(x).", "levels": {"easy": [{"q": "Область определения y = 1/x?", "o": ["x ≠ 0", "x > 0", "все x", "x ≥ 0"], "a": 0, "e": "На ноль делить нельзя."}, {"q": "Функция y = x² — чётная или нечётная?", "o": ["чётная", "нечётная", "ни та ни другая", "периодическая"], "a": 0, "e": "(−x)² = x²."}, {"q": "Наименьший положительный период y = sin x?", "o": ["2π", "π", "π/2", "1"], "a": 0, "e": "Синус повторяется через 2π."}], "medium": [{"q": "Область определения y = √(4 − x)?", "o": ["x ≤ 4", "x ≥ 4", "x < 4", "все x"], "a": 0, "e": "4 − x ≥ 0."}, {"q": "Функция y = x³ − x…", "o": ["нечётная", "чётная", "ни чётная ни нечётная", "периодическая"], "a": 0, "e": "f(−x) = −x³ + x = −f(x)."}, {"q": "Область значений y = x² + 3?", "o": ["[3; +∞)", "(−∞; +∞)", "(3; +∞)", "[0; +∞)"], "a": 0, "e": "x² ≥ 0."}], "hard": [{"q": "Область определения y = √(x − 1)/(x − 3)?", "o": ["[1; 3) ∪ (3; +∞)", "x ≥ 1", "x > 3", "(1; 3)"], "a": 0, "e": "x − 1 ≥ 0 и x ≠ 3."}, {"q": "Период функции y = sin 2x?", "o": ["π", "2π", "π/2", "4π"], "a": 0, "e": "T = 2π/2."}, {"q": "Функция y = x² + x — чётная?", "o": ["ни чётная, ни нечётная", "чётная", "нечётная", "и та и другая"], "a": 0, "e": "f(−x) = x² − x не равно ни f(x), ни −f(x)."}], "olympiad": [{"q": "Период функции y = sin 2x + cos 3x?", "o": ["2π", "π", "6π", "2π/3"], "a": 0, "e": "Периоды π и 2π/3; наименьшее общее кратное — 2π."}, {"q": "Какая функция и чётная, и нечётная одновременно (на ℝ)?", "o": ["y = 0", "y = x", "y = x²", "таких нет"], "a": 0, "e": "f(x) = f(−x) = −f(x) ⇒ f(x) = 0."}, {"q": "Область значений y = 1/(x² + 1)?", "o": ["(0; 1]", "[0; 1]", "(0; +∞)", "[1; +∞)"], "a": 0, "e": "x² + 1 ≥ 1."}]}}, {"id": "a10-inverse", "title": "Обратная функция. Сложная функция", "explain": "Если функция f каждому y из области значений ставит в соответствие ровно один x, у неё есть обратная функция g: g(f(x)) = x. Графики взаимно обратных функций симметричны относительно прямой y = x. Обратная функция существует, например, у любой строго монотонной функции. Сложная функция (композиция) — f(g(x)): сначала вычисляют g, затем f.", "levels": {"easy": [{"q": "Обратная к y = 2x?", "o": ["y = x/2", "y = −2x", "y = 2/x", "y = x − 2"], "a": 0, "e": "Выразим x: x = y/2."}, {"q": "Относительно какой прямой симметричны графики взаимно обратных функций?", "o": ["y = x", "y = 0", "x = 0", "y = −x"], "a": 0, "e": "Меняются местами x и y."}, {"q": "f(x) = x + 1, g(x) = x². Найдите f(g(2)).", "o": ["5", "9", "4", "3"], "a": 0, "e": "g(2) = 4, f(4) = 5."}], "medium": [{"q": "Обратная к y = 3x − 6?", "o": ["y = (x + 6)/3", "y = 3x + 6", "y = x/3 − 6", "y = 1/(3x − 6)"], "a": 0, "e": "x = (y + 6)/3."}, {"q": "f(x) = 2x, g(x) = x − 3. Найдите g(f(x)).", "o": ["2x − 3", "2x − 6", "2(x − 3)", "x − 6"], "a": 0, "e": "g(2x)."}, {"q": "Имеет ли обратную функция y = x² на всей прямой?", "o": ["нет", "да", "только при x < 0", "да, y = √x"], "a": 0, "e": "Значение 4 принимается при x = 2 и x = −2."}], "hard": [{"q": "Обратная к y = x² при x ≥ 0?", "o": ["y = √x", "y = −√x", "y = x/2", "y = 1/x²"], "a": 0, "e": "На этой половине функция монотонна."}, {"q": "Обратная к y = 1/(x − 1)?", "o": ["y = 1 + 1/x", "y = x − 1", "y = 1/(x + 1)", "y = 1 − 1/x"], "a": 0, "e": "x − 1 = 1/y."}, {"q": "f(x) = x², g(x) = x + 1. Найдите f(g(x)) − g(f(x)).", "o": ["2x", "0", "2x + 2", "x² − x"], "a": 0, "e": "(x + 1)² − (x² + 1)."}], "olympiad": [{"q": "Функция f(x) = (2x + 1)/(x − 2). Найдите f(f(x)).", "o": ["x", "1/x", "−x", "2x"], "a": 0, "e": "Проверка: f — сама себе обратная (f(f(x)) = x)."}, {"q": "Найдите f(x), если f(x + 1) = x² + 2x.", "o": ["x² − 1", "x²", "x² + 1", "(x + 1)²"], "a": 0, "e": "x² + 2x = (x + 1)² − 1."}, {"q": "Сколько решений у уравнения f(x) = f⁻¹(x) для возрастающей f(x) = x³?", "o": ["3", "1", "0", "бесконечно много"], "a": 0, "e": "Для возрастающей f решения лежат на y = x: x³ = x → −1, 0, 1."}]}}]}, {"title": "Тригонометрические функции и уравнения", "topics": [{"id": "a10-trig-fn", "title": "Тригонометрические функции и их графики", "explain": "y = sin x и y = cos x определены при всех x, их значения лежат в [−1; 1], период 2π; синус нечётный, косинус чётный. График синуса — синусоида. y = tg x определена при x ≠ π/2 + πk, период π, область значений — все числа. Преобразования: y = A sin(kx + b) растягивает график по вертикали в A раз и меняет период: T = 2π/|k|.", "levels": {"easy": [{"q": "Область значений y = cos x?", "o": ["[−1; 1]", "(−∞; +∞)", "[0; 1]", "[0; 2π]"], "a": 0, "e": "−1 ≤ cos x ≤ 1."}, {"q": "Чётная ли функция y = cos x?", "o": ["да", "нет, нечётная", "ни то ни другое", "только на [0; π]"], "a": 0, "e": "cos(−x) = cos x."}, {"q": "Период y = tg x?", "o": ["π", "2π", "π/2", "нет периода"], "a": 0, "e": "Тангенс повторяется через π."}], "medium": [{"q": "Наибольшее значение y = 3 sin x?", "o": ["3", "1", "−3", "3π"], "a": 0, "e": "sin x ≤ 1."}, {"q": "Период y = cos(x/2)?", "o": ["4π", "π", "2π", "π/2"], "a": 0, "e": "T = 2π/(1/2)."}, {"q": "Нули функции y = sin x?", "o": ["x = πk", "x = π/2 + πk", "x = 2πk", "x = π/4 + πk"], "a": 0, "e": "sin x = 0 в точках, кратных π."}], "hard": [{"q": "Область значений y = 2 − 3cos x?", "o": ["[−1; 5]", "[−3; 3]", "[2; 5]", "[−1; 2]"], "a": 0, "e": "cos x = 1 → −1; cos x = −1 → 5."}, {"q": "Область определения y = tg 2x?", "o": ["x ≠ π/4 + πk/2", "x ≠ π/2 + πk", "x ≠ πk", "все x"], "a": 0, "e": "2x ≠ π/2 + πk."}, {"q": "На каком промежутке y = sin x возрастает?", "o": ["[−π/2; π/2]", "[0; π]", "[π/2; 3π/2]", "[π; 2π]"], "a": 0, "e": "Синус растёт от −1 до 1 на [−π/2; π/2]."}], "olympiad": [{"q": "Наименьшее значение y = sin²x − 4sin x + 5?", "o": ["2", "1", "0", "5"], "a": 0, "e": "t = sin x ∈ [−1; 1]: t² − 4t + 5 убывает на [−1; 1], минимум при t = 1: 1 − 4 + 5 = 2."}, {"q": "Сколько корней у уравнения sin x = x/10?", "o": ["7", "3", "1", "бесконечно много"], "a": 0, "e": "|x| ≤ 10; прямая пересекает синусоиду в 7 точках (включая 0)."}, {"q": "Период функции y = |sin x|?", "o": ["π", "2π", "π/2", "нет периода"], "a": 0, "e": "Отрицательная половина отражается вверх — график повторяется через π."}]}}, {"id": "a10-arcs", "title": "Арксинус, арккосинус, арктангенс", "explain": "arcsin a — угол из [−π/2; π/2], синус которого равен a (|a| ≤ 1). arccos a — угол из [0; π], косинус которого равен a. arctg a — угол из (−π/2; π/2), тангенс которого равен a. Эти функции нужны для записи решений тригонометрических уравнений.", "formula": "arcsin(−a) = −arcsin a;  arccos(−a) = π − arccos a;  arctg(−a) = −arctg a", "levels": {"easy": [{"q": "arcsin(1/2) = ?", "o": ["π/6", "π/3", "5π/6", "π/4"], "a": 0, "e": "sin(π/6) = 1/2, π/6 ∈ [−π/2; π/2]."}, {"q": "arccos 1 = ?", "o": ["0", "π", "π/2", "2π"], "a": 0, "e": "cos 0 = 1."}, {"q": "arctg 1 = ?", "o": ["π/4", "π/3", "π/2", "1"], "a": 0, "e": "tg(π/4) = 1."}], "medium": [{"q": "arccos(−1/2) = ?", "o": ["2π/3", "−π/3", "π/3", "4π/3"], "a": 0, "e": "π − arccos(1/2) = π − π/3."}, {"q": "arcsin(−√3/2) = ?", "o": ["−π/3", "4π/3", "2π/3", "−π/6"], "a": 0, "e": "Нечётность арксинуса."}, {"q": "Имеет ли смысл arcsin 2?", "o": ["нет", "да, π", "да, π/2", "да, 2"], "a": 0, "e": "|sin x| ≤ 1."}], "hard": [{"q": "Вычислите sin(arccos(3/5)).", "o": ["4/5", "3/5", "−4/5", "3/4"], "a": 0, "e": "Угол в [0; π], синус неотрицателен: √(1 − 9/25)."}, {"q": "Вычислите arcsin(sin(5π/6)).", "o": ["π/6", "5π/6", "−π/6", "π/3"], "a": 0, "e": "sin(5π/6) = 1/2, arcsin(1/2) = π/6."}, {"q": "Вычислите arctg √3 + arctg(−1).", "o": ["π/12", "7π/12", "π/3", "−π/12"], "a": 0, "e": "π/3 − π/4."}], "olympiad": [{"q": "Вычислите arcsin x + arccos x при x ∈ [−1; 1].", "o": ["π/2", "π", "0", "зависит от x"], "a": 0, "e": "Известное тождество."}, {"q": "Вычислите cos(2 arcsin(1/3)).", "o": ["7/9", "2/9", "1/9", "8/9"], "a": 0, "e": "cos 2α = 1 − 2sin²α = 1 − 2/9."}, {"q": "Вычислите tg(arctg 2 + arctg 3).", "o": ["−1", "1", "5", "6"], "a": 0, "e": "(2 + 3)/(1 − 6) = −1."}]}}, {"id": "a10-trig-eq", "title": "Тригонометрические уравнения", "explain": "Простейшие уравнения: sin x = a, cos x = a, tg x = a. Их решения записывают общими формулами с целым k. Более сложные уравнения сводят к простейшим: заменой переменной (квадратные относительно sin x или cos x), разложением на множители, делением на cos x (однородные уравнения).", "formula": "sin x = a: x = (−1)ᵏ arcsin a + πk;  cos x = a: x = ±arccos a + 2πk;  tg x = a: x = arctg a + πk", "levels": {"easy": [{"q": "Решите sin x = 0.", "o": ["x = πk", "x = π/2 + πk", "x = 2πk", "нет решений"], "a": 0, "e": "Нули синуса."}, {"q": "Решите cos x = 1.", "o": ["x = 2πk", "x = πk", "x = π/2 + 2πk", "x = π + 2πk"], "a": 0, "e": "Частный случай."}, {"q": "Решите sin x = 2.", "o": ["нет решений", "x = π/2", "x = arcsin 2", "x = 2πk"], "a": 0, "e": "|sin x| ≤ 1."}], "medium": [{"q": "Решите cos x = 1/2.", "o": ["x = ±π/3 + 2πk", "x = π/3 + πk", "x = ±π/6 + 2πk", "x = π/6 + πk"], "a": 0, "e": "arccos(1/2) = π/3."}, {"q": "Решите tg x = √3.", "o": ["x = π/3 + πk", "x = π/6 + πk", "x = ±π/3 + 2πk", "x = π/3 + 2πk"], "a": 0, "e": "Период тангенса π."}, {"q": "Решите 2sin x − 1 = 0.", "o": ["x = (−1)ᵏπ/6 + πk", "x = π/6 + 2πk", "x = ±π/6 + 2πk", "x = π/3 + πk"], "a": 0, "e": "sin x = 1/2."}], "hard": [{"q": "Решите 2cos²x − cos x − 1 = 0.", "o": ["x = 2πk; x = ±2π/3 + 2πk", "x = πk", "x = ±π/3 + 2πk", "x = π/2 + πk"], "a": 0, "e": "cos x = 1 или cos x = −1/2."}, {"q": "Решите sin x = cos x.", "o": ["x = π/4 + πk", "x = π/4 + 2πk", "x = πk", "нет решений"], "a": 0, "e": "Делим на cos x ≠ 0: tg x = 1."}, {"q": "Решите sin 2x = 0.", "o": ["x = πk/2", "x = πk", "x = 2πk", "x = π/4 + πk"], "a": 0, "e": "2x = πk."}], "olympiad": [{"q": "Сколько корней уравнения sin x = 1/2 на отрезке [0; 2π]?", "o": ["2", "1", "4", "бесконечно много"], "a": 0, "e": "π/6 и 5π/6."}, {"q": "Решите sin x + cos x = √2.", "o": ["x = π/4 + 2πk", "x = π/4 + πk", "x = 2πk", "нет решений"], "a": 0, "e": "√2 sin(x + π/4) = √2 → sin(x + π/4) = 1."}, {"q": "Решите 3sin²x + sin x cos x − 2cos²x = 0.", "o": ["x = −π/4 + πk; x = arctg(2/3) + πk", "x = π/4 + πk", "x = arctg 3 + πk", "нет решений"], "a": 0, "e": "Однородное: делим на cos²x: 3tg²x + tg x − 2 = 0 → tg x = −1 или 2/3."}]}}, {"id": "a10-trig-ineq", "title": "Тригонометрические неравенства", "explain": "Простейшие тригонометрические неравенства решают с помощью единичной окружности или графиков: отмечают точки, где функция равна заданному числу, выбирают нужную дугу и добавляют период. Например, sin x > 1/2 при π/6 + 2πk < x < 5π/6 + 2πk.", "check": true, "levels": {"easy": [{"q": "Решите sin x ≤ 1.", "o": ["x — любое число", "нет решений", "x = π/2", "x ≤ π/2"], "a": 0, "e": "Синус никогда не больше 1."}, {"q": "Решите cos x > 1.", "o": ["нет решений", "любое x", "x = 0", "x > 0"], "a": 0, "e": "Косинус не больше 1."}, {"q": "Решите sin x > 1/2 на [0; 2π].", "o": ["(π/6; 5π/6)", "(π/3; 2π/3)", "(0; π)", "(5π/6; 2π)"], "a": 0, "e": "Дуга между π/6 и 5π/6."}], "medium": [{"q": "Решите cos x ≥ 0.", "o": ["[−π/2 + 2πk; π/2 + 2πk]", "[0 + 2πk; π + 2πk]", "[πk; π/2 + πk]", "x — любое"], "a": 0, "e": "Правая половина единичной окружности."}, {"q": "Решите tg x > 1.", "o": ["(π/4 + πk; π/2 + πk)", "(π/4 + 2πk; π/2 + 2πk)", "(0; π/4)", "(π/4 + πk; π + πk)"], "a": 0, "e": "Тангенс растёт от 1 до +∞ на этом промежутке."}, {"q": "Решите sin x < 0.", "o": ["(π + 2πk; 2π + 2πk)", "(2πk; π + 2πk)", "(−π/2 + πk; π/2 + πk)", "нет решений"], "a": 0, "e": "Нижняя половина окружности."}], "hard": [{"q": "Решите cos x < −√2/2.", "o": ["(3π/4 + 2πk; 5π/4 + 2πk)", "(π/4 + 2πk; 3π/4 + 2πk)", "(−π/4 + 2πk; π/4 + 2πk)", "(3π/4; 5π/4)"], "a": 0, "e": "Левая дуга между 3π/4 и 5π/4."}, {"q": "Решите 2sin x + √3 ≥ 0.", "o": ["[−π/3 + 2πk; 4π/3 + 2πk]", "[π/3 + 2πk; 2π/3 + 2πk]", "[−π/3; π/3]", "[4π/3 + 2πk; 5π/3 + 2πk]"], "a": 0, "e": "sin x ≥ −√3/2."}, {"q": "Сколько целых x на [0; 10] удовлетворяет sin x > 0?", "o": ["6", "5", "10", "4"], "a": 0, "e": "x = 1, 2, 3 (до π ≈ 3,14), затем 7, 8, 9 (между 2π ≈ 6,28 и 3π ≈ 9,42)."}], "olympiad": [{"q": "Решите sin x · cos x > 0.", "o": ["(πk; π/2 + πk)", "(2πk; π/2 + 2πk)", "(π/2 + πk; π + πk)", "x — любое"], "a": 0, "e": "sin 2x > 0 → 0 + 2πk < 2x < π + 2πk."}, {"q": "Решите |sin x| < 1/2.", "o": ["(−π/6 + πk; π/6 + πk)", "(−π/6 + 2πk; π/6 + 2πk)", "(π/6 + πk; 5π/6 + πk)", "x — любое"], "a": 0, "e": "Дуги вокруг 0 и π: с периодом π."}, {"q": "Найдите длину множества решений cos x ≥ 1/2 на [0; 2π].", "o": ["2π/3", "π/3", "π", "4π/3"], "a": 0, "e": "[0; π/3] ∪ [5π/3; 2π]: π/3 + π/3."}]}}]}, {"title": "Производная", "topics": [{"id": "a10-limit", "title": "Предел функции. Непрерывность", "explain": "Предел функции в точке — число, к которому приближаются значения f(x), когда x стремится к этой точке. Функция непрерывна в точке, если её предел в этой точке равен значению функции. Графически непрерывная функция рисуется «без отрыва карандаша». Многочлены, синус, косинус непрерывны на всей прямой.", "check": true, "levels": {"easy": [{"q": "lim (x → 2) (3x + 1) = ?", "o": ["7", "6", "5", "не существует"], "a": 0, "e": "Подставим x = 2 — функция непрерывна."}, {"q": "Непрерывна ли y = x² на всей прямой?", "o": ["да", "нет", "только при x > 0", "только в нуле"], "a": 0, "e": "Многочлены непрерывны."}, {"q": "В какой точке разрывна y = 1/x?", "o": ["x = 0", "x = 1", "нигде", "x = −1"], "a": 0, "e": "Функция там не определена."}], "medium": [{"q": "lim (x → 3) (x² − 9)/(x − 3) = ?", "o": ["6", "0", "не существует", "3"], "a": 0, "e": "(x − 3)(x + 3)/(x − 3) = x + 3 → 6."}, {"q": "lim (x → ∞) (2x + 1)/x = ?", "o": ["2", "0", "1", "∞"], "a": 0, "e": "2 + 1/x → 2."}, {"q": "lim (x → 0) sin x / x = ?", "o": ["1", "0", "∞", "не существует"], "a": 0, "e": "Первый замечательный предел."}], "hard": [{"q": "lim (x → ∞) (3x² − x)/(x² + 5) = ?", "o": ["3", "0", "∞", "−1/5"], "a": 0, "e": "Делим на x²."}, {"q": "lim (x → 1) (x³ − 1)/(x − 1) = ?", "o": ["3", "1", "0", "∞"], "a": 0, "e": "x² + x + 1 → 3."}, {"q": "lim (x → 0) sin 3x / x = ?", "o": ["3", "1", "1/3", "0"], "a": 0, "e": "3·sin 3x/(3x) → 3."}], "olympiad": [{"q": "lim (x → ∞) (√(x² + x) − x) = ?", "o": ["1/2", "0", "1", "∞"], "a": 0, "e": "Умножим на сопряжённое: x/(√(x² + x) + x) → 1/2."}, {"q": "lim (n → ∞) (1 + 1/n)ⁿ = ?", "o": ["e ≈ 2,718", "1", "∞", "2"], "a": 0, "e": "Второй замечательный предел."}, {"q": "При каком a функция f(x) = (x² − 4)/(x − 2) при x ≠ 2 и f(2) = a непрерывна?", "o": ["a = 4", "a = 0", "a = 2", "ни при каком"], "a": 0, "e": "Предел при x → 2 равен 4."}]}}, {"id": "a10-derivative", "title": "Производная. Правила дифференцирования", "explain": "Производная показывает мгновенную скорость изменения функции: f'(x) = lim (Δx → 0) Δf/Δx. Физический смысл: производная координаты по времени — скорость. Правила: производная суммы равна сумме производных, постоянный множитель выносится, есть формулы для произведения, частного и сложной функции.", "formula": "(xⁿ)' = nxⁿ⁻¹;  (C)' = 0;  (sin x)' = cos x;  (cos x)' = −sin x;  (uv)' = u'v + uv';  (u/v)' = (u'v − uv')/v²;  (f(g(x)))' = f'(g)·g'", "levels": {"easy": [{"q": "Производная y = x³?", "o": ["3x²", "x²", "3x³", "x⁴/4"], "a": 0, "e": "(xⁿ)' = nxⁿ⁻¹."}, {"q": "Производная константы?", "o": ["0", "1", "сама константа", "x"], "a": 0, "e": "Постоянная не меняется."}, {"q": "Производная y = sin x?", "o": ["cos x", "−cos x", "−sin x", "tg x"], "a": 0, "e": "Табличная производная."}], "medium": [{"q": "Производная y = 4x² − 3x + 7?", "o": ["8x − 3", "8x + 7", "4x − 3", "8x² − 3"], "a": 0, "e": "Почленно."}, {"q": "Производная y = √x?", "o": ["1/(2√x)", "2√x", "√x/2", "1/√x"], "a": 0, "e": "x^(1/2) → (1/2)x^(−1/2)."}, {"q": "Координата x(t) = t² + 3t. Скорость при t = 2?", "o": ["7", "10", "4", "5"], "a": 0, "e": "v = 2t + 3."}], "hard": [{"q": "Производная y = x·sin x?", "o": ["sin x + x cos x", "cos x", "x cos x", "sin x − x cos x"], "a": 0, "e": "Произведение."}, {"q": "Производная y = (2x + 1)⁵?", "o": ["10(2x + 1)⁴", "5(2x + 1)⁴", "(2x + 1)⁴", "10x⁴"], "a": 0, "e": "Сложная функция: 5(2x + 1)⁴·2."}, {"q": "Производная y = 1/x?", "o": ["−1/x²", "1/x²", "ln x", "−1/x"], "a": 0, "e": "x⁻¹ → −x⁻²."}], "olympiad": [{"q": "Производная y = (x² + 1)/x?", "o": ["1 − 1/x²", "2x", "(x² − 1)/x", "1 + 1/x²"], "a": 0, "e": "y = x + 1/x."}, {"q": "Производная y = sin²x?", "o": ["sin 2x", "2 sin x", "cos²x", "2 cos x"], "a": 0, "e": "2 sin x cos x."}, {"q": "Найдите f'(0), если f(x) = x(x − 1)(x − 2)…(x − 5).", "o": ["−120", "120", "0", "−5"], "a": 0, "e": "f'(0) = (0 − 1)(0 − 2)…(0 − 5) = (−1)⁵·5! = −120."}]}}, {"id": "a10-tangent", "title": "Геометрический смысл производной. Касательная", "explain": "Значение производной в точке x₀ равно угловому коэффициенту касательной к графику: k = f'(x₀) = tg α, где α — угол наклона касательной к оси Ox. Уравнение касательной строят по точке касания и угловому коэффициенту.", "formula": "y = f(x₀) + f'(x₀)(x − x₀)", "levels": {"easy": [{"q": "Угловой коэффициент касательной к y = x² в точке x₀ = 3?", "o": ["6", "9", "3", "2"], "a": 0, "e": "f'(x) = 2x."}, {"q": "Производная в точке равна 0. Касательная…", "o": ["горизонтальна", "вертикальна", "под углом 45°", "не существует"], "a": 0, "e": "k = 0."}, {"q": "f'(x₀) = 1. Угол наклона касательной?", "o": ["45°", "0°", "90°", "60°"], "a": 0, "e": "tg α = 1."}], "medium": [{"q": "Уравнение касательной к y = x² в точке x₀ = 1?", "o": ["y = 2x − 1", "y = 2x + 1", "y = x", "y = 2x"], "a": 0, "e": "y = 1 + 2(x − 1)."}, {"q": "В какой точке касательная к y = x² − 4x параллельна оси Ox?", "o": ["x = 2", "x = 4", "x = 0", "x = −2"], "a": 0, "e": "f'(x) = 2x − 4 = 0."}, {"q": "Угол наклона касательной к y = √3·x + 5?", "o": ["60°", "30°", "45°", "90°"], "a": 0, "e": "tg α = √3."}], "hard": [{"q": "Уравнение касательной к y = x³ в точке x₀ = 1?", "o": ["y = 3x − 2", "y = 3x + 1", "y = x", "y = 3x"], "a": 0, "e": "y = 1 + 3(x − 1)."}, {"q": "В какой точке касательная к y = x² параллельна прямой y = 4x − 1?", "o": ["(2; 4)", "(4; 16)", "(1; 1)", "(−2; 4)"], "a": 0, "e": "2x = 4."}, {"q": "Касательная к y = sin x в точке 0?", "o": ["y = x", "y = 0", "y = 1", "y = −x"], "a": 0, "e": "f'(0) = cos 0 = 1, f(0) = 0."}], "olympiad": [{"q": "Сколько касательных к параболе y = x² проходит через точку (0; −1)?", "o": ["2", "1", "0", "бесконечно много"], "a": 0, "e": "y = 2a x − a², при x = 0: −a² = −1 → a = ±1."}, {"q": "Под каким углом пересекаются графики y = x² и y = √x в точке (1; 1)?", "o": ["arctg(3/4) ≈ 37°", "90°", "45°", "0°"], "a": 0, "e": "k₁ = 2, k₂ = 1/2: tg φ = |(2 − 1/2)/(1 + 1)| = 3/4."}, {"q": "При каком b прямая y = 2x + b касается параболы y = x²?", "o": ["b = −1", "b = 1", "b = 0", "b = 2"], "a": 0, "e": "x² − 2x − b = 0 должно иметь один корень: D = 4 + 4b = 0."}]}}, {"id": "a10-extremum", "title": "Применение производной: монотонность и экстремумы", "explain": "Если f'(x) > 0 на промежутке, функция возрастает, если f'(x) < 0 — убывает. Точки, где производная равна нулю или не существует, — критические. Если при переходе через критическую точку производная меняет знак с «+» на «−», это максимум, с «−» на «+» — минимум. Наибольшее и наименьшее значения на отрезке ищут среди значений в критических точках и на концах.", "levels": {"easy": [{"q": "f'(x) > 0 на промежутке. Функция на нём…", "o": ["возрастает", "убывает", "постоянна", "имеет максимум"], "a": 0, "e": "Положительная производная — рост."}, {"q": "Критические точки y = x² − 2x?", "o": ["x = 1", "x = 2", "x = 0", "нет"], "a": 0, "e": "y' = 2x − 2 = 0."}, {"q": "Производная меняет знак с «+» на «−». Это точка…", "o": ["максимума", "минимума", "перегиба", "разрыва"], "a": 0, "e": "Функция сначала растёт, потом убывает."}], "medium": [{"q": "Точка минимума y = x² − 6x + 5?", "o": ["x = 3", "x = −3", "x = 5", "x = 1"], "a": 0, "e": "y' = 2x − 6."}, {"q": "Промежуток убывания y = x³ − 3x?", "o": ["[−1; 1]", "(−∞; −1]", "[1; +∞)", "нигде"], "a": 0, "e": "y' = 3x² − 3 ≤ 0 при |x| ≤ 1."}, {"q": "Наибольшее значение y = −x² + 4x на [0; 3]?", "o": ["4", "3", "0", "−4"], "a": 0, "e": "Вершина x = 2: y = 4."}], "hard": [{"q": "Точки экстремума y = x³ − 3x² + 1?", "o": ["max x = 0, min x = 2", "max x = 2, min x = 0", "min x = 0", "нет"], "a": 0, "e": "y' = 3x(x − 2)."}, {"q": "Наименьшее значение y = x³ − 3x на [0; 2]?", "o": ["−2", "0", "2", "−3"], "a": 0, "e": "Критическая x = 1: y = −2; концы: 0 и 2."}, {"q": "Сколько точек экстремума у y = x³?", "o": ["0", "1", "2", "3"], "a": 0, "e": "y' = 3x² ≥ 0 — знак не меняется."}], "olympiad": [{"q": "Из квадратного листа 12×12 вырезают по углам квадраты и сгибают коробку. При какой стороне вырезов объём максимален?", "o": ["2", "3", "4", "1"], "a": 0, "e": "V = x(12 − 2x)²; V' = (12 − 2x)(12 − 6x) = 0 → x = 2."}, {"q": "Найдите наименьшее значение x + 4/x при x > 0.", "o": ["4", "2", "5", "0"], "a": 0, "e": "y' = 1 − 4/x² = 0 → x = 2, y = 4."}, {"q": "При каких a функция y = x³ + ax возрастает на всей прямой?", "o": ["a ≥ 0", "a > 3", "a < 0", "при любом a"], "a": 0, "e": "y' = 3x² + a ≥ 0 при всех x."}]}}]}], "book": "Алгебра и начала анализа"}, "11": {"sections": [{"title": "Первообразная и интеграл", "topics": [{"id": "a11-antideriv", "title": "Первообразная. Неопределённый интеграл", "explain": "Первообразная F(x) для функции f(x) — функция, производная которой равна f(x). У каждой функции бесконечно много первообразных: они отличаются на постоянную C. Множество всех первообразных называют неопределённым интегралом.", "formula": "∫xⁿdx = xⁿ⁺¹/(n + 1) + C (n ≠ −1);  ∫cos x dx = sin x + C;  ∫sin x dx = −cos x + C;  ∫dx/x = ln|x| + C", "levels": {"easy": [{"q": "Первообразная для f(x) = 2x?", "o": ["x² + C", "2 + C", "2x² + C", "x + C"], "a": 0, "e": "(x²)' = 2x."}, {"q": "Первообразная для f(x) = cos x?", "o": ["sin x + C", "−sin x + C", "cos x + C", "tg x + C"], "a": 0, "e": "(sin x)' = cos x."}, {"q": "Чем отличаются две первообразные одной функции?", "o": ["на постоянную", "на x", "ничем", "в 2 раза"], "a": 0, "e": "F₁ − F₂ = C."}], "medium": [{"q": "∫x³dx = ?", "o": ["x⁴/4 + C", "3x² + C", "x⁴ + C", "4x⁴ + C"], "a": 0, "e": "Формула для степени."}, {"q": "Первообразная f(x) = 3x² − 4x + 1?", "o": ["x³ − 2x² + x + C", "6x − 4 + C", "x³ − 4x² + x + C", "3x³ − 2x² + C"], "a": 0, "e": "Почленно."}, {"q": "∫sin x dx = ?", "o": ["−cos x + C", "cos x + C", "sin x + C", "−sin x + C"], "a": 0, "e": "(−cos x)' = sin x."}], "hard": [{"q": "Найдите первообразную f(x) = 2x, график которой проходит через (1; 5).", "o": ["x² + 4", "x² + 5", "x² − 4", "2x² + 3"], "a": 0, "e": "1 + C = 5."}, {"q": "∫(2x + 1)³dx = ?", "o": ["(2x + 1)⁴/8 + C", "(2x + 1)⁴/4 + C", "3(2x + 1)² + C", "(2x + 1)⁴ + C"], "a": 0, "e": "Делим на 4 и на коэффициент 2."}, {"q": "∫dx/x² = ?", "o": ["−1/x + C", "1/x + C", "ln x² + C", "−2/x³ + C"], "a": 0, "e": "x⁻² → x⁻¹/(−1)."}], "olympiad": [{"q": "Скорость точки v(t) = 6t − 2, x(0) = 3. Найдите x(2).", "o": ["11", "10", "13", "8"], "a": 0, "e": "x(t) = 3t² − 2t + 3 → 12 − 4 + 3."}, {"q": "∫cos²x dx = ?", "o": ["x/2 + sin 2x/4 + C", "sin²x + C", "cos³x/3 + C", "x + sin x + C"], "a": 0, "e": "cos²x = (1 + cos 2x)/2."}, {"q": "Найдите f(x), если f'(x) = 1/√x и f(4) = 5.", "o": ["2√x + 1", "√x + 3", "2√x + 5", "1/(2√x)"], "a": 0, "e": "F = 2√x + C; 4 + C = 5."}]}}, {"id": "a11-integral", "title": "Определённый интеграл. Площадь криволинейной трапеции", "explain": "Определённый интеграл от a до b равен площади криволинейной трапеции под графиком неотрицательной функции. Его вычисляют по формуле Ньютона–Лейбница через любую первообразную. С помощью интегралов находят площади фигур, путь по скорости, работу переменной силы.", "formula": "∫ₐᵇ f(x)dx = F(b) − F(a)", "levels": {"easy": [{"q": "∫₀² 2x dx = ?", "o": ["4", "2", "8", "0"], "a": 0, "e": "x² от 0 до 2."}, {"q": "∫₀¹ 1 dx = ?", "o": ["1", "0", "x", "2"], "a": 0, "e": "Площадь квадрата 1×1."}, {"q": "Формула Ньютона–Лейбница:", "o": ["F(b) − F(a)", "F(a) − F(b)", "f(b) − f(a)", "F(a)·F(b)"], "a": 0, "e": "Разность значений первообразной."}], "medium": [{"q": "∫₁³ x² dx = ?", "o": ["26/3", "9", "8", "27"], "a": 0, "e": "(27 − 1)/3."}, {"q": "∫₀^π sin x dx = ?", "o": ["2", "0", "1", "π"], "a": 0, "e": "−cos π + cos 0 = 2."}, {"q": "Площадь под y = x от 0 до 4?", "o": ["8", "16", "4", "2"], "a": 0, "e": "Треугольник: 4·4/2."}], "hard": [{"q": "Площадь фигуры между y = x² и y = x.", "o": ["1/6", "1/3", "1/2", "1"], "a": 0, "e": "∫₀¹ (x − x²)dx = 1/2 − 1/3."}, {"q": "Площадь фигуры между y = 4 − x² и осью Ox.", "o": ["32/3", "16/3", "8", "16"], "a": 0, "e": "∫₋₂² (4 − x²)dx = 16 − 16/3."}, {"q": "Скорость v = 3t² м/с. Путь за первые 2 с?", "o": ["8 м", "12 м", "6 м", "4 м"], "a": 0, "e": "∫₀² 3t² dt = 8."}], "olympiad": [{"q": "∫₋₁¹ x³ dx = ?", "o": ["0", "1/2", "2", "1/4"], "a": 0, "e": "Нечётная функция на симметричном отрезке."}, {"q": "∫₀¹ √x dx = ?", "o": ["2/3", "1/2", "1", "3/2"], "a": 0, "e": "(2/3)x^(3/2) от 0 до 1."}, {"q": "Объём тела вращения y = √x вокруг Ox на [0; 4]?", "o": ["8π", "16π", "4π", "2π"], "a": 0, "e": "V = π∫₀⁴ x dx = π·8."}]}}]}, {"title": "Степени и корни", "topics": [{"id": "a11-roots", "title": "Корень n-й степени. Степень с рациональным показателем", "explain": "Корень n-й степени из a — число, n-я степень которого равна a. Корень чётной степени извлекают только из неотрицательных чисел, нечётной — из любых. Степень с рациональным показателем: a^(m/n) = ⁿ√(aᵐ) (a > 0). Для таких степеней выполняются те же свойства, что и для целых.", "formula": "ⁿ√(ab) = ⁿ√a·ⁿ√b;  a^(m/n) = ⁿ√(aᵐ);  aᵖ·a^q = a^(p+q)", "levels": {"easy": [{"q": "³√27 = ?", "o": ["3", "9", "−3", "±3"], "a": 0, "e": "3³ = 27."}, {"q": "³√(−8) = ?", "o": ["−2", "2", "не существует", "±2"], "a": 0, "e": "Корень нечётной степени из отрицательного числа существует."}, {"q": "16^(1/2) = ?", "o": ["4", "8", "2", "256"], "a": 0, "e": "√16."}], "medium": [{"q": "8^(2/3) = ?", "o": ["4", "2", "16", "64/3"], "a": 0, "e": "(³√8)² = 4."}, {"q": "⁴√81 = ?", "o": ["3", "9", "±3", "27"], "a": 0, "e": "3⁴ = 81."}, {"q": "Упростите a^(1/2)·a^(1/3).", "o": ["a^(5/6)", "a^(1/6)", "a^(1/5)", "a"], "a": 0, "e": "1/2 + 1/3 = 5/6."}], "hard": [{"q": "Вычислите 27^(−2/3).", "o": ["1/9", "9", "−9", "1/3"], "a": 0, "e": "1/(³√27)² = 1/9."}, {"q": "Вычислите ⁴√(2)·⁴√(8).", "o": ["2", "4", "√2", "16"], "a": 0, "e": "⁴√16."}, {"q": "Решите ³√x = −2.", "o": ["−8", "8", "нет решений", "−6"], "a": 0, "e": "x = (−2)³."}], "olympiad": [{"q": "Сравните ³√3 и √2.", "o": ["³√3 > √2", "³√3 < √2", "равны", "нельзя сравнить"], "a": 0, "e": "Возведём в 6-ю степень: 9 и 8."}, {"q": "Вычислите ³√(2 + √5) + ³√(2 − √5).", "o": ["1", "2", "√5", "0"], "a": 0, "e": "Пусть x — сумма: x³ = 4 − 3x → x = 1."}, {"q": "Решите √(x + 2) = x.", "o": ["2", "−1 и 2", "−1", "нет решений"], "a": 0, "e": "x + 2 = x² → x = 2 или −1; −1 не подходит (корень неотрицателен)."}]}}]}, {"title": "Показательная функция", "topics": [{"id": "a11-exp-fn", "title": "Показательная функция", "explain": "Показательная функция y = aˣ (a > 0, a ≠ 1) определена при всех x, принимает только положительные значения, её график проходит через точку (0; 1). При a > 1 функция возрастает, при 0 < a < 1 — убывает. Особое основание — число e ≈ 2,718; функция eˣ совпадает со своей производной.", "formula": "(eˣ)' = eˣ;  (aˣ)' = aˣ ln a", "levels": {"easy": [{"q": "Через какую точку проходит график y = 5ˣ?", "o": ["(0; 1)", "(1; 0)", "(0; 5)", "(0; 0)"], "a": 0, "e": "a⁰ = 1."}, {"q": "Область значений y = 2ˣ?", "o": ["(0; +∞)", "(−∞; +∞)", "[0; +∞)", "[1; +∞)"], "a": 0, "e": "Степень положительного числа положительна."}, {"q": "Возрастает ли y = (1/3)ˣ?", "o": ["нет, убывает", "да", "постоянна", "сначала растёт"], "a": 0, "e": "Основание меньше 1."}], "medium": [{"q": "Сравните 2^1,5 и 2^1,7.", "o": ["2^1,5 < 2^1,7", "2^1,5 > 2^1,7", "равны", "нельзя сравнить"], "a": 0, "e": "Основание > 1 — функция возрастает."}, {"q": "Производная y = eˣ?", "o": ["eˣ", "xeˣ⁻¹", "ln x", "1"], "a": 0, "e": "Уникальное свойство e."}, {"q": "Сравните (0,5)³ и (0,5)².", "o": ["(0,5)³ < (0,5)²", "(0,5)³ > (0,5)²", "равны", "нельзя сравнить"], "a": 0, "e": "Основание < 1 — убывает."}], "hard": [{"q": "Производная y = e^(3x)?", "o": ["3e^(3x)", "e^(3x)", "3xe^(3x)", "e^(3x)/3"], "a": 0, "e": "Сложная функция."}, {"q": "Область значений y = 2ˣ + 3?", "o": ["(3; +∞)", "(0; +∞)", "[3; +∞)", "все числа"], "a": 0, "e": "Сдвиг вверх на 3."}, {"q": "Наименьшее значение y = 2^(x²)?", "o": ["1", "0", "2", "не существует"], "a": 0, "e": "x² ≥ 0 → 2^(x²) ≥ 1."}], "olympiad": [{"q": "Сколько корней у уравнения 2ˣ = −x?", "o": ["1", "0", "2", "бесконечно много"], "a": 0, "e": "Убывающая прямая и возрастающая экспонента пересекаются один раз (x < 0)."}, {"q": "Вклад растёт на 8% в год. Примерно через сколько лет он удвоится?", "o": ["≈ 9 лет", "≈ 12,5 лет", "≈ 5 лет", "≈ 20 лет"], "a": 0, "e": "Правило «72»: 72/8 = 9 (1,08⁹ ≈ 2)."}, {"q": "Найдите наибольшее значение y = x·e^(−x) при x ≥ 0.", "o": ["1/e", "e", "1", "0"], "a": 0, "e": "y' = e^(−x)(1 − x) = 0 → x = 1."}]}}, {"id": "a11-exp-eq", "title": "Показательные уравнения и неравенства", "explain": "Показательные уравнения решают, приводя обе части к одному основанию: из aᶠ⁽ˣ⁾ = aᵍ⁽ˣ⁾ следует f(x) = g(x). Также используют вынесение общего множителя и замену t = aˣ (t > 0). В неравенствах при основании a > 1 знак сохраняется, при 0 < a < 1 — меняется на противоположный.", "levels": {"easy": [{"q": "Решите 2ˣ = 8.", "o": ["3", "4", "2", "1/3"], "a": 0, "e": "8 = 2³."}, {"q": "Решите 3ˣ = 1.", "o": ["0", "1", "3", "нет решений"], "a": 0, "e": "3⁰ = 1."}, {"q": "Решите 2ˣ = −4.", "o": ["нет решений", "−2", "2", "−4"], "a": 0, "e": "2ˣ > 0 всегда."}], "medium": [{"q": "Решите 5^(x − 1) = 25.", "o": ["3", "2", "1", "26"], "a": 0, "e": "x − 1 = 2."}, {"q": "Решите 4ˣ = 32.", "o": ["2,5", "8", "3", "2"], "a": 0, "e": "2^(2x) = 2⁵."}, {"q": "Решите 2ˣ > 16.", "o": ["x > 4", "x < 4", "x > 8", "x > 2"], "a": 0, "e": "Основание > 1."}], "hard": [{"q": "Решите (1/2)ˣ ≥ 8.", "o": ["x ≤ −3", "x ≥ −3", "x ≥ 3", "x ≤ 3"], "a": 0, "e": "2^(−x) ≥ 2³ → −x ≥ 3."}, {"q": "Решите 4ˣ − 3·2ˣ + 2 = 0.", "o": ["0 и 1", "1 и 2", "0", "нет решений"], "a": 0, "e": "t = 2ˣ: t² − 3t + 2 = 0 → t = 1 или 2."}, {"q": "Решите 3^(x+1) + 3ˣ = 36.", "o": ["2", "3", "1", "9"], "a": 0, "e": "3ˣ(3 + 1) = 36 → 3ˣ = 9."}], "olympiad": [{"q": "Решите 9ˣ − 4·3ˣ + 3 = 0.", "o": ["0 и 1", "1 и 3", "1", "нет решений"], "a": 0, "e": "t = 3ˣ: t = 1 или 3."}, {"q": "Решите 2^(x²) = 16.", "o": ["±2", "2", "4", "±4"], "a": 0, "e": "x² = 4."}, {"q": "Решите 25ˣ < 6·5ˣ − 5.", "o": ["(0; 1)", "(1; 5)", "x < 1", "x > 0"], "a": 0, "e": "t = 5ˣ: t² − 6t + 5 < 0 → 1 < t < 5."}]}}]}, {"title": "Логарифмы", "topics": [{"id": "a11-log", "title": "Логарифм и его свойства", "explain": "Логарифм числа b по основанию a (a > 0, a ≠ 1, b > 0) — показатель степени, в которую нужно возвести a, чтобы получить b. Десятичный логарифм lg b — по основанию 10, натуральный ln b — по основанию e. Основные свойства позволяют превращать умножение в сложение — на этом когда-то работала логарифмическая линейка.", "formula": "a^(logₐb) = b;  logₐ(bc) = logₐb + logₐc;  logₐ(b/c) = logₐb − logₐc;  logₐbⁿ = n·logₐb;  logₐb = log꜀b / log꜀a", "levels": {"easy": [{"q": "log₂8 = ?", "o": ["3", "4", "16", "1/3"], "a": 0, "e": "2³ = 8."}, {"q": "lg 100 = ?", "o": ["2", "10", "100", "1"], "a": 0, "e": "10² = 100."}, {"q": "log₅1 = ?", "o": ["0", "1", "5", "не существует"], "a": 0, "e": "5⁰ = 1."}], "medium": [{"q": "log₃(1/9) = ?", "o": ["−2", "2", "1/2", "−1/2"], "a": 0, "e": "3⁻² = 1/9."}, {"q": "log₂4 + log₂8 = ?", "o": ["5", "12", "32", "6"], "a": 0, "e": "log₂32."}, {"q": "lg 2 + lg 5 = ?", "o": ["1", "7", "lg 7", "10"], "a": 0, "e": "lg 10."}], "hard": [{"q": "Вычислите 2^(log₂7).", "o": ["7", "2", "14", "log₂7"], "a": 0, "e": "Основное логарифмическое тождество."}, {"q": "Вычислите log₄8.", "o": ["3/2", "2", "2/3", "1/2"], "a": 0, "e": "log₂8/log₂4 = 3/2."}, {"q": "Вычислите log₂24 − log₂3.", "o": ["3", "21", "8", "log₂21"], "a": 0, "e": "log₂8."}], "olympiad": [{"q": "Вычислите log₂3·log₃4·log₄5·…·log₁₅16.", "o": ["4", "16", "1", "15"], "a": 0, "e": "Цепочка сокращается до log₂16."}, {"q": "Вычислите 25^(log₅3).", "o": ["9", "3", "15", "25"], "a": 0, "e": "(5²)^(log₅3) = 5^(2log₅3) = 3²."}, {"q": "Сколько цифр в числе 2¹⁰⁰ (lg 2 ≈ 0,301)?", "o": ["31", "30", "100", "301"], "a": 0, "e": "lg 2¹⁰⁰ ≈ 30,1 → 31 цифра."}]}}, {"id": "a11-log-fn", "title": "Логарифмическая функция", "explain": "Логарифмическая функция y = logₐx (a > 0, a ≠ 1) обратна показательной. Она определена только при x > 0, принимает все действительные значения, её график проходит через (1; 0). При a > 1 возрастает, при 0 < a < 1 — убывает. Производная натурального логарифма: (ln x)' = 1/x.", "formula": "(ln x)' = 1/x;  (logₐx)' = 1/(x ln a)", "levels": {"easy": [{"q": "Область определения y = log₃x?", "o": ["x > 0", "x ≥ 0", "все x", "x ≠ 0"], "a": 0, "e": "Логарифм определён только для положительных чисел."}, {"q": "Через какую точку проходит y = log₇x?", "o": ["(1; 0)", "(0; 1)", "(7; 0)", "(0; 0)"], "a": 0, "e": "log 1 = 0."}, {"q": "Производная y = ln x?", "o": ["1/x", "ln x", "x", "eˣ"], "a": 0, "e": "Табличная производная."}], "medium": [{"q": "Возрастает ли y = log₀,₅x?", "o": ["нет, убывает", "да", "постоянна", "только при x > 1"], "a": 0, "e": "Основание меньше 1."}, {"q": "Область определения y = lg(x − 3)?", "o": ["x > 3", "x ≥ 3", "x > 0", "x ≠ 3"], "a": 0, "e": "x − 3 > 0."}, {"q": "Сравните log₂5 и log₂7.", "o": ["log₂5 < log₂7", "log₂5 > log₂7", "равны", "нельзя сравнить"], "a": 0, "e": "Основание > 1 — возрастает."}], "hard": [{"q": "Производная y = ln(3x)?", "o": ["1/x", "3/x", "1/(3x)", "ln 3"], "a": 0, "e": "ln 3 + ln x — константа исчезает."}, {"q": "Область определения y = log₂(x² − 4)?", "o": ["(−∞; −2) ∪ (2; +∞)", "x > 2", "(−2; 2)", "x > 4"], "a": 0, "e": "x² − 4 > 0."}, {"q": "Сравните log₀,₃2 и 0.", "o": ["log₀,₃2 < 0", "log₀,₃2 > 0", "= 0", "нельзя сравнить"], "a": 0, "e": "Основание < 1, аргумент > 1."}], "olympiad": [{"q": "Наименьшее значение y = x − ln x при x > 0?", "o": ["1", "0", "e", "−1"], "a": 0, "e": "y' = 1 − 1/x = 0 → x = 1, y = 1."}, {"q": "Что больше: log₂3 или log₃2?", "o": ["log₂3", "log₃2", "равны", "нельзя сравнить"], "a": 0, "e": "log₂3 > 1 > log₃2."}, {"q": "Касательная к y = ln x в точке x = 1?", "o": ["y = x − 1", "y = x", "y = 1", "y = x + 1"], "a": 0, "e": "f(1) = 0, f'(1) = 1."}]}}, {"id": "a11-log-eq", "title": "Логарифмические уравнения и неравенства", "explain": "Логарифмические уравнения решают, используя определение логарифма или приводя к виду logₐf(x) = logₐg(x) ⇒ f(x) = g(x). Обязательно проверяют область допустимых значений: под знаком логарифма должны быть положительные выражения. В неравенствах при основании > 1 знак сохраняется, при основании от 0 до 1 — меняется, и снова учитывают ОДЗ.", "levels": {"easy": [{"q": "Решите log₂x = 3.", "o": ["8", "6", "9", "1/8"], "a": 0, "e": "x = 2³."}, {"q": "Решите lg x = 0.", "o": ["1", "0", "10", "нет решений"], "a": 0, "e": "10⁰ = 1."}, {"q": "Решите log₃x = −1.", "o": ["1/3", "−3", "3", "нет решений"], "a": 0, "e": "x = 3⁻¹."}], "medium": [{"q": "Решите log₂(x − 1) = 2.", "o": ["5", "3", "4", "1"], "a": 0, "e": "x − 1 = 4."}, {"q": "Решите log₅(2x + 3) = log₅7.", "o": ["2", "5", "7", "1"], "a": 0, "e": "2x + 3 = 7."}, {"q": "Решите log₂x > 3.", "o": ["x > 8", "x > 6", "x < 8", "0 < x < 8"], "a": 0, "e": "Основание > 1."}], "hard": [{"q": "Решите log₂x + log₂(x − 2) = 3.", "o": ["4", "−2 и 4", "−2", "2"], "a": 0, "e": "x(x − 2) = 8 → x = 4 (x = −2 вне ОДЗ)."}, {"q": "Решите log₀,₅x > 1.", "o": ["(0; 0,5)", "x > 0,5", "x < 0,5", "(0,5; 1)"], "a": 0, "e": "Основание < 1: 0 < x < 0,5."}, {"q": "Решите lg²x − 3lg x + 2 = 0.", "o": ["10 и 100", "1 и 2", "10", "100"], "a": 0, "e": "t = lg x: t = 1 или 2."}], "olympiad": [{"q": "Решите log₃(x² − 8) = log₃(2x).", "o": ["4", "−2 и 4", "−2", "нет решений"], "a": 0, "e": "x² − 2x − 8 = 0 → 4 или −2; при −2 аргумент 2x < 0."}, {"q": "Решите log₂(x + 1) < 2.", "o": ["(−1; 3)", "x < 3", "(0; 3)", "x > −1"], "a": 0, "e": "0 < x + 1 < 4."}, {"q": "Решите x^(lg x) = 100x.", "o": ["100 и 0,1", "10", "100", "0,1"], "a": 0, "e": "Прологарифмируем: lg²x = 2 + lg x → lg x = 2 или −1."}]}}]}, {"title": "Элементы математической статистики", "topics": [{"id": "a11-stat", "title": "Случайные величины. Математическое ожидание и дисперсия", "explain": "Случайная величина принимает значения с определёнными вероятностями. Математическое ожидание — «среднее» значение с учётом вероятностей: M(X) = Σ xᵢpᵢ. Дисперсия показывает разброс: D(X) = M(X²) − (M(X))², а стандартное отклонение — корень из дисперсии.", "formula": "M(X) = Σ xᵢ·pᵢ;  D(X) = M(X²) − M(X)²;  σ = √D", "check": true, "levels": {"easy": [{"q": "Математическое ожидание числа очков на кубике?", "o": ["3,5", "3", "6", "21"], "a": 0, "e": "(1 + 2 + … + 6)/6."}, {"q": "Что показывает дисперсия?", "o": ["разброс значений вокруг среднего", "среднее значение", "наибольшее значение", "число опытов"], "a": 0, "e": "Мера рассеивания."}, {"q": "Стандартное отклонение — это…", "o": ["корень из дисперсии", "квадрат дисперсии", "среднее", "размах"], "a": 0, "e": "σ = √D."}], "medium": [{"q": "X: 0 с вероятностью 0,4 и 10 с вероятностью 0,6. M(X)?", "o": ["6", "5", "4", "10"], "a": 0, "e": "0·0,4 + 10·0,6."}, {"q": "Дисперсия постоянной величины?", "o": ["0", "1", "сама величина", "бесконечна"], "a": 0, "e": "Разброса нет."}, {"q": "Сумма вероятностей всех значений случайной величины?", "o": ["1", "0", "100", "зависит от величины"], "a": 0, "e": "Распределение полное."}], "hard": [{"q": "Числа 2, 4, 6. Дисперсия (как среднее квадратов отклонений)?", "o": ["8/3", "4", "2", "16"], "a": 0, "e": "Среднее 4: (4 + 0 + 4)/3."}, {"q": "Лотерея: выигрыш 1000 ₸ с вероятностью 0,01, билет стоит 50 ₸. Ожидаемый выигрыш на билет?", "o": ["−40 ₸", "10 ₸", "950 ₸", "−50 ₸"], "a": 0, "e": "1000·0,01 − 50."}, {"q": "Как изменится дисперсия, если все значения умножить на 3?", "o": ["в 9 раз", "в 3 раза", "не изменится", "в √3 раз"], "a": 0, "e": "D(3X) = 9D(X)."}], "olympiad": [{"q": "Монету бросают 100 раз. Математическое ожидание числа орлов и дисперсия?", "o": ["50 и 25", "50 и 50", "50 и 5", "100 и 50"], "a": 0, "e": "Биномиальное распределение: np и np(1 − p)."}, {"q": "Как изменится дисперсия, если ко всем значениям прибавить 5?", "o": ["не изменится", "увеличится на 5", "на 25", "в 5 раз"], "a": 0, "e": "Сдвиг не меняет разброс."}, {"q": "Игра: бросают кубик; при «6» получаешь 30 ₸, иначе платишь 5 ₸. Выгодна ли игра?", "o": ["да, ожидание +0,83 ₸", "нет, −5 ₸", "ничья", "нет, −0,83 ₸"], "a": 0, "e": "30/6 − 5·5/6 = 5 − 4,17 ≈ 0,83."}]}}]}], "book": "Алгебра и начала анализа"}}};
